def _annotated_recovery_event(event, *, rule_id, pack_id, cite, grade,
                              mode):
    """Attach authored provenance to an already validated physical event."""
    if not isinstance(event, dict) or event.get('status') != 'perfects':
        return None
    result = dict(event)
    result.update({
        'source_rule_id': str(rule_id),
        'source_pack': pack_id,
        'source_cite': cite,
        'source_grade': str(grade or 'recovery'),
        'source_mode': str(mode or 'body_pair'),
    })
    return result


def lilly_recovery_rule_witnesses(rule_id, rule_data, args, chrt,
                                   context=None, match=None, pack_id=None):
    """Resolve the physical recovery clock declared by one Lilly rule.

    Snapshot testimonies only gain a clock when their current aspect is
    applying/exact *and* the exact contact survives the authored station/sign
    boundary.  Placement, dignity, house-tenancy and generic strength rules
    remain explicitly ``clock = "none"`` in the corpus.
    """
    del match  # The physical event is recomputed from canonical chart truth.
    metadata = (rule_data or {}).get('recovery_timing')
    if not isinstance(metadata, dict):
        return ()
    clock = str(metadata.get('clock') or '').lower().replace('-', '_')
    if clock == 'none':
        return ()
    rid = str(rule_id or '')
    if clock != 'perfection' or rid not in LILLY_RECOVERY_TIMED_RULE_IDS:
        return ()
    grade = str(metadata.get('grade') or 'recovery')
    mode = str(metadata.get('mode') or 'body_pair')
    cite = (rule_data or {}).get('cite')
    semantic_args = dict(args or {})

    def house_from_context(key, default):
        value = (context or {}).get(key, default)
        return _resolved_house_spec(value, context)

    def body_event(pid_a, pid_b, *, aspects=None, boundary=None,
                   required_applicator_pid=None, event_mode=None):
        event = _body_recovery_perfection_event(
            chrt, pid_a, pid_b,
            aspects=tuple(aspects or semantic_args.get(
                'aspects', _PTOLEMAIC_ASPECTS,
            )),
            boundary=boundary or semantic_args.get('boundary', 'pair_signs'),
            orb=semantic_args.get('orb'),
            orb_policy=semantic_args.get('orb_policy'),
            required_applicator_pid=required_applicator_pid,
            horizon_days=semantic_args.get('horizon_days'),
        )
        return _annotated_recovery_event(
            event, rule_id=rid, pack_id=pack_id, cite=cite, grade=grade,
            mode=event_mode or mode,
        )

    def point_event(actor_pid, longitude, *, aspects=None, label=None,
                    endpoint_kind='axis', endpoint_house=None,
                    boundary=None, event_mode=None):
        event = _point_recovery_perfection_event(
            chrt, actor_pid, longitude,
            aspects=tuple(aspects or semantic_args.get(
                'aspects', _PTOLEMAIC_ASPECTS,
            )),
            boundary=boundary or semantic_args.get('boundary', 'actor_sign'),
            orb=semantic_args.get('orb'),
            orb_policy=semantic_args.get('orb_policy'),
            point_orb_policy=semantic_args.get('point_orb_policy', 'profile'),
            aspect_frame=semantic_args.get('aspect_frame', 'profile'),
            endpoint_kind=endpoint_kind, endpoint_label=label,
            endpoint_house=endpoint_house,
            horizon_days=semantic_args.get('horizon_days'),
        )
        return _annotated_recovery_event(
            event, rule_id=rid, pack_id=pack_id, cite=cite, grade=grade,
            mode=event_mode or mode,
        )

    raw_events = []
    with semantic_scope(semantic_args, context, root=True):
        moon = astrology.SE_MOON
        if rid == 'moon_applies_querent_lord':
            lord = _lord_of_house(
                chrt, house_from_context('querent_house', 1),
            )
            raw_events.append(body_event(
                moon, lord, required_applicator_pid=moon,
            ))
        elif rid == 'moon_applies_quesited_lord':
            lord = _lord_of_house(
                chrt, house_from_context('quesited_house', 2),
            )
            raw_events.append(body_event(
                moon, lord, required_applicator_pid=moon,
            ))
        elif rid == 'moon_applies_lord_12th':
            raw_events.append(body_event(
                moon, _lord_of_house(chrt, 12),
                required_applicator_pid=moon,
            ))
        elif rid == 'moon_applies_dispositor':
            moon_body = _planet(chrt, moon)
            moon_lon = _lon(moon_body) if moon_body is not None else None
            dispositor = (
                _sign_ruler_at(chrt, _sign(moon_lon))
                if moon_lon is not None else None
            )
            raw_events.append(body_event(
                moon, dispositor, required_applicator_pid=moon,
            ))
        elif rid == 'dispositor_separates_then_applies_h2_cusp_lost':
            sequence = _lilly_moon_dispositor_recovery_sequence_event(
                chrt,
                separating_houses=tuple(semantic_args.get(
                    'separating_houses', (12, 8, 6),
                )),
                applying_house=semantic_args.get('applying_house', 2),
                aspects=tuple(semantic_args.get(
                    'aspects', _PTOLEMAIC_ASPECTS,
                )), boundary=semantic_args.get('boundary', 'actor_sign'),
                tie_policy=semantic_args.get('tie_policy', 'unique'),
                orb=semantic_args.get('orb'),
                orb_policy=semantic_args.get('orb_policy', 'lilly_moiety'),
                point_orb_policy=semantic_args.get(
                    'point_orb_policy', 'profile',
                ), aspect_frame=semantic_args.get('aspect_frame', 'degree'),
                dignity_frame=semantic_args.get('dignity_frame', 'lilly'),
                lookback_days=semantic_args.get('lookback_days', 32.0),
                max_lookback_days=semantic_args.get(
                    'max_lookback_days', 4096.0,
                ),
            )
            if sequence is not None:
                event = dict(sequence['application'])
                event.update({
                    'endpoint_kind': 'house_cusp',
                    'endpoint_label': f"H{sequence['applying_house']} cusp",
                    'endpoint_house': sequence['applying_house'],
                    'endpoint_longitude': sequence['cusp_longitude'],
                    'applicator_pids': (sequence['dispositor_pid'],),
                    'actor_basis': 'body_motion_toward_fixed_point',
                })
                raw_events.append(_annotated_recovery_event(
                    event, rule_id=rid, pack_id=pack_id, cite=cite,
                    grade=grade, mode=mode,
                ))
        elif rid in (
                'recovery_pof_lord_applies_l1',
                'recovery_pof_lord_applies_moon'):
            target = (
                _lord_of_house(chrt, 1)
                if rid.endswith('_l1') else moon
            )
            event = _fortune_lord_future_aspect_event(
                chrt, target,
                aspects=tuple(semantic_args.get(
                    'aspects', _PTOLEMAIC_ASPECTS,
                )), directions=tuple(semantic_args.get(
                    'directions', ('applying', 'exact'),
                )), boundary=semantic_args.get('boundary', 'pair_signs'),
                tie_policy=semantic_args.get('tie_policy', 'unique'),
                orb=semantic_args.get('orb'),
                orb_policy=semantic_args.get('orb_policy', 'lilly_moiety'),
                aspect_frame=semantic_args.get('aspect_frame', 'degree'),
                dignity_frame=semantic_args.get('dignity_frame', 'lilly'),
                horizon_days=semantic_args.get('horizon_days'),
            )
            if event is not None:
                actor = int(event['fortune_lord_pid'])
                enriched = dict(event)
                contributions = _aspect_closing_contributions(
                    chrt, actor, int(event['target_pid']),
                    float(event['angle']),
                )
                applicators = tuple(sorted(
                    pid for pid, value in contributions.items()
                    if value > 1.0e-12
                ))
                if actor in applicators:
                    enriched.update({
                        'party_pids': (actor, int(event['target_pid'])),
                        'applicator_pids': applicators,
                        'closing_contributions': contributions,
                        'actor_basis': 'signed_error_closing_contribution',
                    })
                    raw_events.append(_annotated_recovery_event(
                        enriched, rule_id=rid, pack_id=pack_id, cite=cite,
                        grade=grade, mode=mode,
                    ))
        elif rid in (
                'recovery_pof_lord_applies_l2',
                'recovery_pof_lord_applies_fortune_place'):
            if rid.endswith('_l2'):
                endpoint_house = 2
                endpoint_lon = _house_cusp_lon(chrt, 2)
                endpoint_kind = 'house_cusp'
            else:
                endpoint_house = None
                endpoint_lon = None
                endpoint_kind = 'lot'
            event = _fortune_lord_future_point_event(
                chrt,
                aspects=tuple(semantic_args.get(
                    'aspects', _PTOLEMAIC_ASPECTS,
                )), boundary=semantic_args.get('boundary', 'actor_sign'),
                tie_policy=semantic_args.get('tie_policy', 'unique'),
                orb=semantic_args.get('orb'),
                orb_policy=semantic_args.get('orb_policy', 'lilly_moiety'),
                point_orb_policy=semantic_args.get(
                    'point_orb_policy', 'profile',
                ), aspect_frame=semantic_args.get('aspect_frame', 'degree'),
                dignity_frame=semantic_args.get('dignity_frame', 'lilly'),
                horizon_days=semantic_args.get('horizon_days'),
                point_longitude=endpoint_lon,
                endpoint_kind=endpoint_kind,
                endpoint_house=endpoint_house,
            )
            if event is not None:
                enriched = dict(event)
                enriched.update({
                    'applicator_pids': (int(event['fortune_lord_pid']),),
                    'actor_basis': 'body_motion_toward_fixed_point',
                    'endpoint_label': (
                        'H2 cusp' if endpoint_house == 2 else 'Fortune'
                    ),
                })
                raw_events.append(_annotated_recovery_event(
                    enriched, rule_id=rid, pack_id=pack_id, cite=cite,
                    grade=grade, mode=mode,
                ))
        elif rid == 'recovery_l1_l2_perfection':
            raw_events.append(body_event(
                _lord_of_house(chrt, 1), _lord_of_house(chrt, 2),
            ))
        elif rid == 'recovery_direct_application_l8_l2':
            raw_events.append(body_event(
                _lord_of_house(chrt, 8), _lord_of_house(chrt, 2),
            ))
        elif rid in (
                'recovery_translation_l8_l2',
                'translation_recovery_lost_object'):
            witness = _translation_witness(
                chrt, context=context,
                from_house=(8 if rid == 'recovery_translation_l8_l2' else None),
                to_house=(2 if rid == 'recovery_translation_l8_l2' else None),
                orb=semantic_args.get('orb', 6.0),
                aspects=tuple(semantic_args.get(
                    'aspects', _PTOLEMAIC_ASPECTS,
                )), reception_levels=tuple(semantic_args.get(
                    'reception_levels', ('domicile', 'triplicity', 'term'),
                )), require_reception=semantic_args.get(
                    'require_reception', True,
                ), translator=semantic_args.get('translator'),
                direction=semantic_args.get('direction', 'either'),
            )
            if witness is not None:
                translator = int(witness['translator'])
                target = int(witness['second_lord'])
                event = dict(witness['target_event'])
                contributions = _aspect_closing_contributions(
                    chrt, translator, target, float(event['angle']),
                )
                applicators = tuple(sorted(
                    pid for pid, value in contributions.items()
                    if value > 1.0e-12
                ))
                if translator in applicators:
                    event.update({
                        'actor_pid': translator, 'target_pid': target,
                        'party_pids': (translator, target),
                        'applicator_pids': applicators,
                        'closing_contributions': contributions,
                        'actor_basis': 'signed_error_closing_contribution',
                    })
                    raw_events.append(_annotated_recovery_event(
                        event, rule_id=rid, pack_id=pack_id, cite=cite,
                        grade=grade, mode=mode,
                    ))
        elif rid == 'dispositor_sextiles_asc_lost':
            moon_body = _planet(chrt, moon)
            moon_lon = _lon(moon_body) if moon_body is not None else None
            dispositor = (
                _sign_ruler_at(chrt, _sign(moon_lon))
                if moon_lon is not None else None
            )
            raw_events.append(point_event(
                dispositor, _point_lon(chrt, 'ASC'), aspects=(60,),
                label='ASC', endpoint_kind='axis', endpoint_house=1,
            ))
        elif rid == 'dispositor_aspects_moon_lost':
            moon_body = _planet(chrt, moon)
            moon_lon = _lon(moon_body) if moon_body is not None else None
            dispositor = (
                _sign_ruler_at(chrt, _sign(moon_lon))
                if moon_lon is not None else None
            )
            raw_events.append(body_event(dispositor, moon))
        elif rid == 'benefic_aspects_asc_lost':
            asc = _point_lon(chrt, 'ASC')
            for benefic in (astrology.SE_JUPITER, astrology.SE_VENUS):
                raw_events.append(point_event(
                    benefic, asc, label='ASC', endpoint_kind='axis',
                    endpoint_house=1,
                ))
        elif rid == 'moon_aspects_asc_lost':
            raw_events.append(point_event(
                moon, _point_lon(chrt, 'ASC'), label='ASC',
                endpoint_kind='axis', endpoint_house=1,
            ))
        elif rid == 'recovery_moon_in_7_trines_l1':
            raw_events.append(body_event(
                moon, _lord_of_house(chrt, 1), aspects=(120,),
            ))
        elif rid == 'recovery_moon_in_2_trines_l2':
            raw_events.append(body_event(
                moon, _lord_of_house(chrt, 2), aspects=(120,),
            ))
        elif rid == 'recovery_moon_in_2_squares_sun_in_12':
            raw_events.append(body_event(
                moon, astrology.SE_SUN, aspects=(90,),
            ))
        elif rid == 'recovery_moon_in_10_trines_planet_in_2':
            for target in (
                    astrology.SE_SUN, astrology.SE_MERCURY,
                    astrology.SE_VENUS, astrology.SE_MARS,
                    astrology.SE_JUPITER, astrology.SE_SATURN):
                body = _planet(chrt, target)
                longitude = _lon(body) if body is not None else None
                if longitude is None or _house_of(chrt, longitude) != 2:
                    continue
                raw_events.append(body_event(
                    moon, target, aspects=(120,),
                ))
        elif rid == 'recovery_luminaries_aspect_in_angles':
            raw_events.append(body_event(
                astrology.SE_SUN, moon,
                aspects=tuple(semantic_args.get(
                    'aspects', _PTOLEMAIC_ASPECTS,
                )),
            ))
        elif rid == 'recovery_moon_asc_jupiter':
            raw_events.append(body_event(
                moon, astrology.SE_JUPITER, aspects=(0,),
            ))
        elif rid == 'recovery_sun_moon_trine':
            raw_events.append(body_event(
                astrology.SE_SUN, moon, aspects=(120,),
            ))

    normalized = []
    for event in raw_events:
        if event is None:
            continue
        timing = _lilly_recovery_timing_event(
            chrt, context=context, perfection_event=event,
            house_frame=semantic_args.get('house_frame'),
        )
        if timing is not None:
            normalized.append(timing)
    return tuple(normalized)


def _lilly_recovery_physical_identity(witness):
    endpoint = witness.get('endpoint')
    angle = round(float(witness.get('angle', 0.0)), 8)
    if isinstance(endpoint, dict):
        parties = tuple(int(pid) for pid in witness.get('party_pids') or ())
        return (
            'point', parties,
            str(endpoint.get('kind') or 'zodiacal_point'),
            round(float(endpoint.get('longitude', 0.0)) % 360.0, 8),
            angle,
        )
    return (
        'body', tuple(sorted(
            int(pid) for pid in witness.get('party_pids') or ()
        )), angle,
    )


def aggregate_lilly_recovery_timing(witnesses, tie_tolerance_days=1.0e-6,
                                    context=None,
                                    selection_policy=None):
    """Deduplicate physical clocks and apply one explicit display policy.

    Lilly does not say that a recovery-grade testimony must outrank an earlier
    hope-grade clock.  The default therefore returns every distinct physical
    witness.  The prior recovery-before-hope rule remains available only as an
    explicitly named editorial reading.
    """
    try:
        tolerance = max(0.0, float(tie_tolerance_days))
    except (TypeError, ValueError):
        tolerance = 1.0e-6
    policy_context = context
    if selection_policy is not None:
        policy_context = dict(context or {})
        policy_context['recovery_clock_selection'] = selection_policy
    requested_policy, policy, policy_origin = _lilly_recovery_context_token(
        policy_context, 'recovery_clock_selection',
        _LILLY_RECOVERY_CLOCK_SELECTIONS, 'all_witnesses',
    )
    # Accept the v1 transport spelling for direct API callers, but always emit
    # the canonical saved-context token and mark the policy editorial.
    if isinstance(selection_policy, str) and selection_policy in {
            'recovery-before-hope_then-earliest_exact',
            'recovery_before_hope_then_earliest_exact'}:
        requested_policy = selection_policy
        policy = 'recovery_before_hope_then_earliest'
        policy_origin = 'legacy_api_alias'
    rows = []
    for raw in tuple(witnesses or ()):
        if not isinstance(raw, dict) or raw.get('status') != 'timed':
            continue
        try:
            exact_jd = float(raw['exact_jd'])
        except (KeyError, TypeError, ValueError):
            continue
        if not math.isfinite(exact_jd):
            continue
        row = dict(raw)
        row['provenance'] = dict(raw.get('provenance') or {})
        row['provenance']['sources'] = [
            dict(source) for source in row['provenance'].get('sources', ())
            if isinstance(source, dict)
        ]
        identity = _lilly_recovery_physical_identity(row)
        duplicate = next((
            existing for existing in rows
            if existing['_physical_identity'] == identity
            and abs(float(existing['exact_jd']) - exact_jd) <= tolerance
        ), None)
        if duplicate is None:
            row['_physical_identity'] = identity
            rows.append(row)
            continue
        known_sources = {
            (
                source.get('rule_id'), source.get('pack'),
                source.get('cite'), source.get('grade'), source.get('mode'),
            )
            for source in duplicate['provenance'].get('sources', ())
        }
        for source in row['provenance'].get('sources', ()):
            key = (
                source.get('rule_id'), source.get('pack'),
                source.get('cite'), source.get('grade'), source.get('mode'),
            )
            if key not in known_sources:
                duplicate['provenance']['sources'].append(dict(source))
                known_sources.add(key)
        if (duplicate.get('grade') != 'recovery'
                and row.get('grade') == 'recovery'):
            duplicate['grade'] = 'recovery'

    rows.sort(key=lambda row: (
        float(row['exact_jd']), _lilly_recovery_physical_identity(row),
    ))
    for row in rows:
        row.pop('_physical_identity', None)
        row['source_rule_ids'] = tuple(dict.fromkeys(
            source.get('rule_id')
            for source in row.get('provenance', {}).get('sources', ())
            if source.get('rule_id')
        ))
    if not rows:
        return {
            'schema': 'lilly.recovery-aggregate.v2',
            'state': 'none', 'strongest_grade': None,
            'earliest_physical_exact_jd': None,
            'selected_exact_jd': None,
            'selected_witnesses': (), 'alternates': (), 'witnesses': (),
            'selection_policy': policy,
            'requested_selection_policy': requested_policy,
            'selection_policy_origin': policy_origin,
            'selection_authority': (
                'editorial' if policy == (
                    'recovery_before_hope_then_earliest'
                ) else 'source_neutral'
            ),
        }
    earliest_physical_jd = min(float(row['exact_jd']) for row in rows)
    strongest_grade = None
    selected_jd = None
    if policy == 'all_witnesses':
        selected = tuple(rows)
        state = 'all_witnesses'
    elif policy == 'earliest_physical':
        selected_jd = earliest_physical_jd
        selected = tuple(
            row for row in rows
            if abs(float(row['exact_jd']) - selected_jd) <= tolerance
        )
        state = 'unique' if len(selected) == 1 else 'co_earliest'
    else:
        grade_priority = {'recovery': 0, 'hope': 1}
        strongest_grade = min(
            (str(row.get('grade') or 'recovery') for row in rows),
            key=lambda grade: (grade_priority.get(grade, 99), grade),
        )
        lane = [
            row for row in rows
            if str(row.get('grade') or 'recovery') == strongest_grade
        ]
        selected_jd = min(float(row['exact_jd']) for row in lane)
        selected = tuple(
            row for row in lane
            if abs(float(row['exact_jd']) - selected_jd) <= tolerance
        )
        state = 'unique' if len(selected) == 1 else 'co_earliest'
    selected_ids = {id(row) for row in selected}
    alternates = tuple(row for row in rows if id(row) not in selected_ids)
    return {
        'schema': 'lilly.recovery-aggregate.v2',
        'state': state,
        'strongest_grade': strongest_grade,
        'earliest_physical_exact_jd': earliest_physical_jd,
        'selected_exact_jd': selected_jd,
        'selected_witnesses': selected,
        'alternates': alternates,
        'witnesses': tuple(rows),
        'selection_policy': policy,
        'requested_selection_policy': requested_policy,
        'selection_policy_origin': policy_origin,
        'selection_authority': (
            'editorial' if policy == (
                'recovery_before_hope_then_earliest'
            ) else 'source_neutral'
        ),
    }


def format_lilly_recovery_timing_evidence(witnesses):
    """Compact visible proof that a matching rule owns a physical clock."""
    tokens = []
    for witness in tuple(witnesses or ()):
        if not isinstance(witness, dict) or witness.get('status') != 'timed':
            continue
        applicators = tuple(witness.get('applicator_pids') or ())
        actor_label = '+'.join(
            planet_name_from_id(int(pid)).title() for pid in applicators
        ) or 'current exact contact'
        endpoint = witness.get('endpoint')
        if isinstance(endpoint, dict):
            target_label = (
                endpoint.get('label')
                or str(endpoint.get('kind') or 'fixed point').replace('_', ' ')
            )
        else:
            applicator_set = {int(pid) for pid in applicators}
            targets = [
                planet_name_from_id(int(pid)).title()
                for pid in witness.get('party_pids') or ()
                if int(pid) not in applicator_set
            ]
            target_label = '+'.join(targets) or 'mutual contact'
        symbolic = witness.get('symbolic') or {}
        units = '/'.join(symbolic.get('unit_candidates') or ()) or 'unresolved'
        basis = str(symbolic.get('place_basis') or 'both_candidates')
        selection = str(symbolic.get('selection') or 'unselected')
        if selection == 'selected':
            selected_unit = str(symbolic.get('selected_unit') or '')
            symbolic_token = (
                f"symbolic {float(symbolic.get('amount')):.3f} "
                f"{selected_unit}; basis {basis}"
            )
        else:
            requested = str(symbolic.get('requested_unit') or 'unselected')
            reason = str(symbolic.get('selection_reason') or 'unit_not_selected')
            symbolic_token = (
                f"symbolic units {units} unselected; basis {basis}; "
                f"requested {requested}; reason {reason}"
            )
        tokens.append(
            f"[recovery-clock:{actor_label}\N{RIGHTWARDS ARROW}{target_label}; "
            f"physical exact in {float(witness['days']):.3f}d; "
            f"JD {float(witness['exact_jd']):.6f}; "
            f"arc {_degree_token(float(witness['arc']))}; "
            f"{symbolic_token}]"
        )
    return ' · '.join(tokens)


def angles_in_signs(chrt, points=('ASC', 'MC', 'DSC', 'IC'), signs=(), **_):
    """Every named astronomical angle occupies one of ``signs``."""
    allowed = {int(sign) % 12 for sign in tuple(signs)}
    if not allowed:
        return False
    for point in tuple(points):
        longitude = _point_lon(chrt, point)
        if longitude is None or _sign(longitude) not in allowed:
            return False
    return True


def _point_sign_membership_event(
        chrt, points=('ASC', 'MC', 'DSC', 'IC'), signs=(),
        point_frame='profile'):
    """Typed sign membership for axial degrees or angular sign-places.

    ``angles_in_signs`` intentionally means the signs containing the four
    astronomical angle degrees.  Source packs sometimes instead mean the
    first/tenth/seventh/fourth places.  Keeping that choice in ``point_frame``
    prevents an MC/IC sign test from silently collapsing a whole-sign reading
    back to the quadrant angle degree.
    """
    allowed = {int(sign) % 12 for sign in tuple(signs)}
    names = tuple(str(point or '').upper() for point in tuple(points))
    frame = _effective_point_frame(point_frame)
    if (not allowed or not names or frame in
            ('unresolved', 'none', 'disabled')):
        return None
    if frame in ('sign', 'whole_sign', 'sign_configuration'):
        geometry = 'angular_sign_place_membership'
        resolved_frame = 'sign'
        longitude_for = _point_sign_anchor_lon
    elif frame in ('degree', 'zodiacal_degree', 'axial_degree'):
        geometry = 'angle_degree_sign_membership'
        resolved_frame = 'degree'
        longitude_for = _point_lon
    else:
        return None
    rows = []
    for name in names:
        longitude = longitude_for(chrt, name)
        if longitude is None or _sign(longitude) not in allowed:
            return None
        rows.append({
            'point': name,
            'longitude': float(longitude),
            'sign': _sign(longitude),
            'point_frame': resolved_frame,
            'role': 'angular_place' if resolved_frame == 'sign' else 'angle',
        })
    return {
        'points': tuple(rows),
        'point_frame': resolved_frame,
        'geometry': geometry,
    }


def point_in_signs(chrt, points=('ASC', 'MC', 'DSC', 'IC'), signs=(),
                   point_frame='profile', **_):
    """All named points occupy ``signs`` in the selected point frame."""
    return _point_sign_membership_event(
        chrt, points=points, signs=signs, point_frame=point_frame,
    ) is not None


def _lilly_rumour_fixed_sequence_event(chrt):
    """Bound Moon/Mercury modality plus actual last/next lunar events."""
    fixed = {1, 4, 7, 10}
    moon = _planet(chrt, astrology.SE_MOON)
    mercury = _planet(chrt, astrology.SE_MERCURY)
    if (moon is None or mercury is None
            or _sign(_lon(moon)) not in fixed
            or _sign(_lon(mercury)) not in fixed):
        return None
    last = _last_perfected_predicate_event(
        chrt, astrology.SE_MOON,
        aspects=_PTOLEMAIC_ASPECTS, scope='history',
        min_days_ago=1.0e-6,
        tie_policy='unique',
    )
    if last is None or last['target_pid'] not in (
            astrology.SE_MARS, astrology.SE_SATURN):
        return None
    next_event = _next_perfected_aspect_event(
        chrt, astrology.SE_MOON,
        tuple(pid for pid in _PLANET_IDS.values()
              if pid != astrology.SE_MOON),
        aspects=_PTOLEMAIC_ASPECTS, boundary='actor_sign',
        require_current_application=False,
    )
    if (next_event is None or next_event.get('status') != 'perfects'
            or next_event['target_pid'] not in (
                astrology.SE_SUN, astrology.SE_JUPITER,
                astrology.SE_VENUS,
            )):
        return None
    target = _planet(chrt, next_event['target_pid'])
    target_house = _house_of_frame(chrt, _lon(target), 'profile')
    if target_house not in (1, 4, 7, 10):
        return None
    return {
        'last': last,
        'next': next_event,
        'target_house': target_house,
    }


def lilly_rumour_fixed_sequence(chrt, **_):
    """Lilly's complete fixed-sign/last/next/angular-Fortune testimony."""
    return _lilly_rumour_fixed_sequence_event(chrt) is not None


def _lilly_consideration_voc_event(chrt, context=None, **_):
    """One VOC witness with Lilly's two qualifications kept as metadata.

    Lilly does not withdraw the void-of-course fact in Taurus, Cancer,
    Sagittarius, or Pisces: he says the Moon still performs *somewhat* there.
    Likewise, unusually strong principal significators are an exception to
    the blanket "all matters go hardly" wording.  Neither qualification is a
    second vote, so this event owns the fact and both grades together.
    """
    if not moon_void_of_course(chrt):
        return None
    moon = _planet(chrt, astrology.SE_MOON)
    moon_lon = _lon(moon) if moon is not None else None
    if moon_lon is None:
        return None
    sign = _sign(moon_lon)
    sign_mitigation = sign in {1, 3, 8, 11}
    principal_rows = []
    houses = []
    for key, fallback in (('querent_house', 1), ('quesited_house', None)):
        house = _coerce_house_number((context or {}).get(key, fallback))
        if house is not None and house not in houses:
            houses.append(house)
    for house in houses:
        pid = _lord_of_house(chrt, house)
        if pid is None:
            continue
        state = _lilly_siege_condition_event(chrt, pid, house)
        principal_rows.append({
            'house': house, 'pid': pid,
            'complete': bool(state.get('fortitude', {}).get('complete')),
            'strong_and_fortunate': bool(
                state.get('strong') and state.get('fortunate')
            ),
            'fortitude': state.get('fortitude'),
        })
    principal_scope_complete = bool(principal_rows) and all(
        row['complete'] for row in principal_rows
    )
    strong_principals = bool(
        principal_scope_complete
        and all(row['strong_and_fortunate'] for row in principal_rows)
    )
    if sign_mitigation and strong_principals:
        grade = 'sign_mitigation_and_strong_principals'
    elif strong_principals:
        grade = 'strong_principals_exception'
    elif sign_mitigation:
        grade = 'sign_mitigation_somewhat_performs'
    else:
        grade = 'unmitigated'
    return {
        'moon_longitude': float(moon_lon) % 360.0,
        'moon_sign': sign,
        'sign_mitigation': sign_mitigation,
        'principal_scope_complete': principal_scope_complete,
        'strong_principals': strong_principals,
        'principals': tuple(principal_rows),
        'grade': grade,
    }


