def _lilly_testimony_balance_event(chrt):
    pids = (
        astrology.SE_VENUS, astrology.SE_JUPITER,
        astrology.SE_MARS, astrology.SE_SATURN,
    )
    events = {pid: _lilly_fortitude_event(chrt, pid) for pid in pids}
    complete = all(event.get('complete') for event in events.values())
    fortunes = (
        events[astrology.SE_VENUS]['net']
        + events[astrology.SE_JUPITER]['net']
    )
    infortunes = (
        events[astrology.SE_MARS]['net']
        + events[astrology.SE_SATURN]['net']
    )
    margin = fortunes - infortunes
    return {
        'complete': complete, 'events': events,
        'fortunes': fortunes, 'infortunes': infortunes,
        'margin': margin, 'balanced': bool(complete and margin == 0),
        'dignity_frame': 'lilly',
        'house_frame': 'regiomontanus_5deg',
    }


def lilly_testimony_balance_available(chrt, **_):
    return bool(_lilly_testimony_balance_event(chrt).get('complete'))


def _lilly_rumour_true_compound_event(chrt, **_):
    """The ancient fixed-angle report clause as one atomic witness."""
    if not angles_in_signs(
            chrt, points=('ASC', 'MC', 'DSC', 'IC'),
            signs=(1, 4, 7, 10)):
        return None
    sequence = _lilly_rumour_fixed_sequence_event(chrt)
    if sequence is None:
        return None
    return {
        **sequence,
        'angles': tuple({
            'point': point, 'longitude': float(_point_lon(chrt, point)),
            'sign': _sign(_point_lon(chrt, point)),
        } for point in ('ASC', 'MC', 'DSC', 'IC')),
    }


