def _any_ancient_solar_phase_events(
        chrt,
        bodies=('mercury', 'venus', 'mars', 'jupiter', 'saturn'),
        phase='under_rays',
        visibility_policy='hellenistic_15_degree',
        visibility_policy_context_key=None,
        transition_policy='exact_event_day',
        transition_policy_context_key=None,
        context=None, search_days=450.0, **_):
    events = []
    seen = set()
    for body in tuple(bodies):
        pid = _classical_pid(body)
        if pid is None or pid in seen or pid in (
                astrology.SE_SUN, astrology.SE_MOON):
            continue
        seen.add(pid)
        event = _ancient_solar_phase_event(
            chrt,
            body=pid,
            phase=phase,
            visibility_policy=visibility_policy,
            visibility_policy_context_key=visibility_policy_context_key,
            transition_policy=transition_policy,
            transition_policy_context_key=transition_policy_context_key,
            context=context,
            search_days=search_days,
        )
        if event is not None and event.get('matched'):
            events.append(event)
    events.sort(key=lambda row: int(row['pid']))
    return tuple(events)


def any_ancient_solar_phase(
        chrt,
        bodies=('mercury', 'venus', 'mars', 'jupiter', 'saturn'),
        phase='under_rays',
        visibility_policy='hellenistic_15_degree',
        visibility_policy_context_key=None,
        transition_policy='exact_event_day',
        transition_policy_context_key=None,
        context=None, **_):
    return bool(_any_ancient_solar_phase_events(
        chrt,
        bodies=bodies,
        phase=phase,
        visibility_policy=visibility_policy,
        visibility_policy_context_key=visibility_policy_context_key,
        transition_policy=transition_policy,
        transition_policy_context_key=transition_policy_context_key,
        context=context,
    ))


