def body_in_detriment(chrt, body='mercury', **_):
    """Body is in its detriment — the sign opposite its domicile.

    Lilly CA I p.~11578 table: detriment is a **−5 debility**, equal in
    weight to domicile. Aries' Almutens engine does NOT subtract this
    (acknowledged divergence); this predicate exposes the condition for
    pack rules to honor it explicitly.
    """
    pid = _pid(body)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    opposite = (_sign(_lon(p)) + 6) % 12
    return _sign_ruler_at(chrt, opposite) == pid


def body_in_fall(chrt, body='mercury', **_):
    """Body is in its fall — the sign opposite its exaltation. Lilly's
    **−4 debility** (CA I p.~11578)."""
    pid = _pid(body)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    opposite = (_sign(_lon(p)) + 6) % 12
    return _exaltation_ruler_at(chrt, opposite) == pid


def body_peregrine(chrt, body='mercury', **_):
    """Body is peregrine — has no essential dignity (domicile, exaltation,
    triplicity, term, or face) in its current sign. Lilly's **−5 debility**
    (CA I p.~11578); Lilly: *"In a Sign wherein he hath no essentiall
    dignity."*
    """
    pid = _pid(body)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    rulers = _dignity_rulers_at(chrt, _lon(p))
    if not rulers:
        return False
    return not any(pid in tuple(values) for values in rulers.values())


def lord_of_house_in_detriment(chrt, house=1, **_):
    """Lord of `house` is in its detriment."""
    pid = _lord_of_house(chrt, house)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    opposite = (_sign(_lon(p)) + 6) % 12
    return _sign_ruler_at(chrt, opposite) == pid


def lord_of_house_in_fall(chrt, house=1, **_):
    """Lord of `house` is in its fall."""
    pid = _lord_of_house(chrt, house)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    opposite = (_sign(_lon(p)) + 6) % 12
    return _exaltation_ruler_at(chrt, opposite) == pid


def lord_of_house_peregrine(chrt, house=1, **_):
    """Lord of `house` is peregrine — no essential dignity in current sign."""
    pid = _lord_of_house(chrt, house)
    if pid is None:
        return False
    # Reuse body_peregrine logic via a temporary name lookup.
    from astrology import SE_SUN, SE_MOON, SE_MERCURY, SE_VENUS, SE_MARS, SE_JUPITER, SE_SATURN
    name_by_pid = {SE_SUN:'sun', SE_MOON:'moon', SE_MERCURY:'mercury',
                   SE_VENUS:'venus', SE_MARS:'mars', SE_JUPITER:'jupiter',
                   SE_SATURN:'saturn'}
    body_name = name_by_pid.get(pid)
    if body_name is None:
        return False
    return body_peregrine(chrt, body=body_name)


def body_in_own_dignity(chrt, body='venus', level='domicile', **_):
    """Named planet sits in a sign where IT has the named essential dignity.

    `level` may be any of the five essential dignities. The selected
    dignity frame decides the source tables and whether triplicity is
    sect-specific (Lilly), all Dorothean lords (Hellenistic), or the active
    chart option.
    """
    pid = _pid(body)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    rulers = _dignity_rulers_at(chrt, _lon(p))
    return pid in tuple(rulers.get(str(level).lower(), ()))


def both_luminaries_in_houses(chrt, houses=(), **_):
    """Both Sun and Moon occupy any of the given houses (typically a single
    house — Lilly: *"Sun and Moon in the 10th, sudden recovery."*).
    """
    sun = _planet(chrt, astrology.SE_SUN)
    moon = _planet(chrt, astrology.SE_MOON)
    if sun is None or moon is None:
        return False
    sh = _house_of(chrt, _lon(sun))
    mh = _house_of(chrt, _lon(moon))
    target = set(int(h) for h in houses)
    return sh in target and mh in target


def lord_of_house_in_own_dignity(chrt, house=None, level='exaltation', **_):
    """Lord of `house` sits in a sign where it has the named essential dignity.

    `level` may be any of the five essential dignities. Used for Lilly:
    *"If the Lord of the 2nd be in his exaltation, there is a great hope
    of recovery."*  Table doctrine comes from the effective dignity frame.
    """
    if house is None:
        return False
    pid = _lord_of_house(chrt, house)
    if pid is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    rulers = _dignity_rulers_at(chrt, _lon(p))
    return pid in tuple(rulers.get(str(level).lower(), ()))


def _body_above_horizon(chrt, pid):
    """Astronomical hemisphere state, independent of house division."""
    body = _planet(chrt, pid)
    if body is None:
        return None
    above = getattr(body, 'abovehorizon', None)
    if above is not None:
        return bool(above)
    try:
        return float(body.speculums[0][planets.Planet.PL_ELV]) >= 0.0
    except Exception:
        return None


def body_above_horizon(chrt, body='sun', **_):
    """Named body is in the astronomical hemisphere above the earth."""
    return _body_above_horizon(chrt, _pid(body)) is True


def body_below_horizon(chrt, body='sun', **_):
    """Named body is in the astronomical hemisphere below the earth."""
    return _body_above_horizon(chrt, _pid(body)) is False


def both_luminaries_below_horizon(chrt, **_):
    """Both Sun and Moon are astronomically below the earth.

    Lilly CA II, "Aphorismes concerning Recovery":
    *"When both the Luminaries are under the earth it cannot be recovered."*
    This is a horizon fact, not tenancy in houses 1–6; it therefore remains
    invariant when the semantic house frame changes.
    """
    return (
        _body_above_horizon(chrt, astrology.SE_SUN) is False
        and _body_above_horizon(chrt, astrology.SE_MOON) is False
    )


def both_luminaries_aspect_house(chrt, house=1,
                                   aspects=(0, 60, 90, 120, 180),
                                   orb=6.0, orb_policy='profile',
                                   point_orb_policy='profile',
                                   point_frame='profile', **_):
    """Sun AND Moon each form one of the named aspects to the given house cusp.

    Lilly CA II, "Aphorismes concerning Recovery":
    *"the Sun together with the Moon, beholding the Ascendant cannot be
    lost but will, shortly be discovered."*
    """
    cusp = _house_cusp_lon(chrt, house)
    if cusp is None:
        return False
    sun = _planet(chrt, astrology.SE_SUN)
    moon = _planet(chrt, astrology.SE_MOON)
    if sun is None or moon is None:
        return False
    return (
        _body_aspects_longitude(
            chrt, astrology.SE_SUN, cusp, tuple(aspects), orb, orb_policy,
            point_orb_policy, point_frame, endpoint_kind='house_cusp',
        )
        and _body_aspects_longitude(
            chrt, astrology.SE_MOON, cusp, tuple(aspects), orb, orb_policy,
            point_orb_policy, point_frame, endpoint_kind='house_cusp',
        )
    )


