def _lilly_lord_hour_application_state(
        chrt, *, house=1, aspects=_PTOLEMAIC_ASPECTS,
        boundary='pair_signs', orb=None, orb_policy='lilly_moiety',
        context=None, **_):
    selected_house = _resolved_house_spec(house, context)
    lord = _lord_of_house(chrt, selected_house)
    hour_lord = _hour_lord_pid(chrt)
    if lord is None or hour_lord is None or lord == hour_lord:
        return {'status': 'invalid', 'complete': False}
    result = _strict_body_application_state(
        chrt, lord, hour_lord, aspects=aspects, boundary=boundary,
        orb=orb, orb_policy=orb_policy, require_named_actor=True,
    )
    result.update({
        'house': selected_house, 'lord_pid': lord,
        'hour_lord_pid': hour_lord,
    })
    return result


