def _ordered_contact_event(
        chrt, actor_pid, past_targets, future_targets,
        aspects=_PTOLEMAIC_ASPECTS, boundary='actor_sign',
        orb_policy=None, past_scope='history',
        tie_policy='require_unique'):
    """Exact prior/next body-contact chronology with an explicit tie rule.

    The historical and future searches stay shared across source packs; only
    the source-owned aspect set, stopping course, orb metadata, and handling
    of simultaneous roots vary.  ``co_roles`` preserves every tied target,
    while ``require_unique`` fails closed instead of selecting by planet id.
    """
    selected_tie = str(tie_policy or '').strip().lower().replace('-', '_')
    if selected_tie not in {'require_unique', 'co_roles'}:
        return None
    past = _last_perfected_aspect_event(
        chrt, actor_pid, tuple(past_targets), aspects=tuple(aspects),
        orb_policy=orb_policy, scope=past_scope,
    )
    if past is None:
        return None
    future = _next_perfected_aspect_event(
        chrt, actor_pid, tuple(future_targets), aspects=tuple(aspects),
        boundary=boundary, require_current_application=False,
        orb_policy=orb_policy,
    )
    if not isinstance(future, dict) or future.get('status') != 'perfects':
        return None
    past_events = tuple(past.get('tied_events') or (past,))
    future_events = tuple(future.get('tied_events') or (future,))
    if (selected_tie == 'require_unique'
            and (len(past_events) != 1 or len(future_events) != 1)):
        return None
    return {
        'past': dict(past), 'future': dict(future),
        'past_events': tuple(dict(row) for row in past_events),
        'future_events': tuple(dict(row) for row in future_events),
        'actor_pid': int(actor_pid), 'aspects': tuple(float(a) for a in aspects),
        'boundary': str(boundary), 'past_scope': str(past_scope),
        'tie_policy': selected_tie,
    }


def _lilly_ordered_contact_event(
        chrt, actor_pid, past_targets, future_targets,
        aspects=_LILLY_CONTACT_ASPECTS, boundary='actor_sign'):
    return _ordered_contact_event(
        chrt, actor_pid, past_targets, future_targets,
        aspects=aspects, boundary=boundary,
        orb_policy='lilly_moiety', past_scope='history',
        tie_policy='require_unique',
    )


def _lilly_partnership_moon_sequence_event(chrt, outcome='good_to_bad'):
    routes = {
        'good_to_good': (_LILLY_FORTUNES, _LILLY_FORTUNES),
        'good_to_bad': (_LILLY_FORTUNES, _LILLY_INFORTUNES),
        'bad_to_good': (_LILLY_INFORTUNES, _LILLY_FORTUNES),
        'bad_to_bad': (_LILLY_INFORTUNES, _LILLY_INFORTUNES),
    }
    selected = str(outcome or '').strip().lower()
    targets = routes.get(selected)
    if targets is None:
        return None
    comparison_universe = tuple(dict.fromkeys(
        _LILLY_FORTUNES + _LILLY_INFORTUNES
    ))
    event = _lilly_ordered_contact_event(
        chrt, astrology.SE_MOON,
        comparison_universe, comparison_universe,
    )
    if (event is None
            or int(event['past']['target_pid']) not in targets[0]
            or int(event['future']['target_pid']) not in targets[1]):
        return None
    return {'outcome': selected, **event}


def lilly_partnership_moon_sequence(
        chrt, outcome='good_to_bad', **_):
    return _lilly_partnership_moon_sequence_event(
        chrt, outcome=outcome,
    ) is not None


def _lilly_partnership_strength_event(
        chrt, context=None, minimum_margin=0, **partner_args):
    partner = _lilly_partner_actor_event(
        chrt, context=context, **partner_args,
    )
    l1 = _lord_of_house(chrt, 1)
    l2 = _lord_of_house(chrt, 2)
    partner_gain_house = (
        (partner['partner_house'] % 12) + 1 if partner else None
    )
    partner_gain = (
        _lord_of_house(chrt, partner_gain_house)
        if partner_gain_house else None
    )
    if partner is None or None in (l1, l2, partner_gain):
        return None
    try:
        margin = max(0, int(minimum_margin))
    except (TypeError, ValueError):
        return None
    sides = {
        'querent': tuple(dict.fromkeys((l1, l2))),
        'partner': tuple(dict.fromkeys((partner['actor_pid'], partner_gain))),
    }
    fortitudes = {}
    scores = {}
    for side, pids in sides.items():
        rows = tuple(_lilly_fortitude_event(chrt, pid) for pid in pids)
        if not all(row.get('complete') for row in rows):
            return None
        fortitudes[side] = rows
        scores[side] = sum(int(row['net']) for row in rows)
    difference = scores['querent'] - scores['partner']
    if difference > margin:
        outcome = 'querent_advantage'
    elif difference < -margin:
        outcome = 'partner_advantage'
    else:
        outcome = 'tie'
    return {
        'outcome': outcome, 'scores': scores, 'fortitudes': fortitudes,
        'side_pids': sides, 'minimum_margin': margin,
        'partner_gain_house': partner_gain_house, 'partner': partner,
    }


def lilly_partnership_strength(
        chrt, outcome='tie', context=None, minimum_margin=0,
        selection='source_default',
        selection_context_key='partner_significator', partner_house=7,
        near_cusp_orb=5.0, house_frame='regiomontanus_5deg', **_):
    event = _lilly_partnership_strength_event(
        chrt, context=context, minimum_margin=minimum_margin,
        selection=selection, selection_context_key=selection_context_key,
        partner_house=partner_house, near_cusp_orb=near_cusp_orb,
        house_frame=house_frame,
    )
    return bool(event and event['outcome'] == str(outcome))


def _lilly_partnership_querent_gain_event(chrt):
    fortunes = tuple(
        pid for pid in _LILLY_FORTUNES
        if _lilly_body_house(chrt, pid) == 2
    )
    infortunes = tuple(
        pid for pid in _LILLY_INFORTUNES
        if _lilly_body_house(chrt, pid) == 2
    )
    south = _south_node_lon(chrt)
    south_in_h2 = bool(
        south is not None
        and _house_of_frame(chrt, south, 'regiomontanus_5deg') == 2
    )
    adverse = bool(infortunes or south_in_h2)
    favorable = bool(fortunes)
    if favorable and not adverse:
        outcome = 'gain'
    elif adverse and not favorable:
        outcome = 'loss'
    elif favorable and adverse:
        outcome = 'mixed'
    else:
        return None
    return {
        'outcome': outcome, 'fortune_pids': fortunes,
        'infortune_pids': infortunes, 'south_node_in_h2': south_in_h2,
    }


def lilly_partnership_querent_gain(chrt, outcome='loss', **_):
    event = _lilly_partnership_querent_gain_event(chrt)
    return bool(event and event['outcome'] == str(outcome))


def _lilly_removing_place_quality_event(chrt):
    places = {}
    for role, house in (('current', 4), ('destination', 7)):
        fortunes = tuple(
            pid for pid in _LILLY_FORTUNES
            if _lilly_body_house(chrt, pid) == house
        )
        infortunes = tuple(
            pid for pid in _LILLY_INFORTUNES
            if _lilly_body_house(chrt, pid) == house
        )
        places[role] = {
            'house': house, 'fortune_pids': fortunes,
            'infortune_pids': infortunes,
            'quality': (
                'good' if fortunes and not infortunes else
                'ill' if infortunes and not fortunes else
                'mixed' if fortunes or infortunes else 'unassessed'
            ),
        }
    current = places['current']['quality']
    destination = places['destination']['quality']
    if current == 'ill' and destination == 'good':
        outcome = 'remove'
    elif current == 'good' and destination == 'ill':
        outcome = 'stay'
    elif current == 'unassessed' and destination == 'unassessed':
        return None
    else:
        outcome = 'mixed'
    return {'outcome': outcome, 'places': places}


def lilly_removing_place_quality(chrt, outcome='mixed', **_):
    event = _lilly_removing_place_quality_event(chrt)
    return bool(event and event['outcome'] == str(outcome))


def _lilly_removing_class_sequence_event(
        chrt, actor='lord_1', outcome='remove'):
    if str(actor).strip().lower() in ('lord_1', 'l1'):
        actor_pid = _lord_of_house(chrt, 1)
        actor_role = 'lord_1'
    elif str(actor).strip().lower() == 'moon':
        actor_pid = astrology.SE_MOON
        actor_role = 'moon'
    else:
        return None
    selected = str(outcome or '').strip().lower()
    route = {
        'remove': (_LILLY_INFORTUNES, _LILLY_FORTUNES),
        'stay': (_LILLY_FORTUNES, _LILLY_INFORTUNES),
    }.get(selected)
    if actor_pid is None or route is None:
        return None
    universe = tuple(
        pid for pid in dict.fromkeys(
            _LILLY_FORTUNES + _LILLY_INFORTUNES
        ) if pid != actor_pid
    )
    event = _lilly_ordered_contact_event(
        chrt, actor_pid, universe, universe,
    )
    if (event is None
            or int(event['past']['target_pid']) not in route[0]
            or int(event['future']['target_pid']) not in route[1]):
        return None
    return {'outcome': selected, 'actor_role': actor_role, **event}


def lilly_removing_class_sequence(
        chrt, actor='lord_1', outcome='remove', **_):
    return _lilly_removing_class_sequence_event(
        chrt, actor=actor, outcome=outcome,
    ) is not None


def _lilly_removing_endpoint_strength_event(
        chrt, actor='moon', minimum_margin=0):
    if str(actor).strip().lower() == 'moon':
        actor_pid = astrology.SE_MOON
        actor_role = 'moon'
    elif str(actor).strip().lower() in ('lord_1', 'l1'):
        actor_pid = _lord_of_house(chrt, 1)
        actor_role = 'lord_1'
    else:
        return None
    if actor_pid is None:
        return None
    universe = tuple(
        pid for pid in _PLANET_IDS.values() if pid != actor_pid
    )
    sequence = _lilly_ordered_contact_event(
        chrt, actor_pid, universe, universe,
    )
    if sequence is None:
        return None
    past_pid = int(sequence['past']['target_pid'])
    future_pid = int(sequence['future']['target_pid'])
    if past_pid == future_pid:
        return None
    past = _lilly_fortitude_event(chrt, past_pid)
    future = _lilly_fortitude_event(chrt, future_pid)
    if not (past.get('complete') and future.get('complete')):
        return None
    try:
        margin = max(0, int(minimum_margin))
    except (TypeError, ValueError):
        return None
    difference = int(future['net']) - int(past['net'])
    outcome = 'remove' if difference > margin else 'stay'
    return {
        **sequence, 'outcome': outcome, 'actor_role': actor_role,
        'past_fortitude': past, 'future_fortitude': future,
        'difference': difference, 'minimum_margin': margin,
    }


def lilly_removing_endpoint_strength(
        chrt, actor='moon', outcome='remove', minimum_margin=0, **_):
    event = _lilly_removing_endpoint_strength_event(
        chrt, actor=actor, minimum_margin=minimum_margin,
    )
    return bool(event and event['outcome'] == str(outcome))


def _lilly_removing_recommendation_event(chrt, minimum_margin=0):
    recommendations = []
    neutral = []
    place = _lilly_removing_place_quality_event(chrt)
    if place is not None:
        witness = {'route': 'paired_place_quality', 'event': place}
        if place['outcome'] in ('remove', 'stay'):
            recommendations.append({
                **witness, 'recommendation': place['outcome'],
            })
        else:
            neutral.append(witness)

    moon_last = _last_perfected_aspect_event(
        chrt, astrology.SE_MOON,
        tuple(dict.fromkeys(_LILLY_FORTUNES + _LILLY_INFORTUNES)),
        aspects=_LILLY_CONTACT_ASPECTS, orb_policy='lilly_moiety',
        scope='history',
    )
    if (moon_last is not None
            and len(tuple(moon_last.get('tied_events') or (moon_last,))) == 1):
        target = int(moon_last['target_pid'])
        recommendation = (
            'stay' if target in _LILLY_FORTUNES else 'remove'
        )
        recommendations.append({
            'route': 'moon_last_exact_contact',
            'recommendation': recommendation,
            'event': dict(moon_last),
        })

    for recommendation in ('remove', 'stay'):
        sequence = _lilly_removing_class_sequence_event(
            chrt, actor='lord_1', outcome=recommendation,
        )
        if sequence is not None:
            recommendations.append({
                'route': 'l1_last_next_class_sequence',
                'recommendation': recommendation, 'event': sequence,
            })

    endpoint = _lilly_removing_endpoint_strength_event(
        chrt, actor='moon', minimum_margin=minimum_margin,
    )
    if endpoint is not None:
        recommendations.append({
            'route': 'moon_endpoint_fortitude_comparison',
            'recommendation': endpoint['outcome'], 'event': endpoint,
        })
    if not recommendations:
        return ({'outcome': 'mixed', 'witnesses': (),
                 'neutral_witnesses': tuple(neutral)} if neutral else None)
    outcomes = {row['recommendation'] for row in recommendations}
    outcome = next(iter(outcomes)) if len(outcomes) == 1 else 'conflict'
    return {
        'outcome': outcome, 'witnesses': tuple(recommendations),
        'neutral_witnesses': tuple(neutral),
        'minimum_margin': max(0, int(minimum_margin)),
    }


def lilly_removing_recommendation(
        chrt, outcome='conflict', minimum_margin=0, **_):
    event = _lilly_removing_recommendation_event(
        chrt, minimum_margin=minimum_margin,
    )
    return bool(event and event['outcome'] == str(outcome))


