_LILLY_FERTILE_SIGNS = frozenset((3, 7, 11))
_LILLY_BARREN_SIGNS = frozenset((4, 5))
_LILLY_COMMON_SIGNS = frozenset((2, 5, 8, 11))
_LILLY_FIXED_SIGNS = frozenset((1, 4, 7, 10))
_LILLY_MOVABLE_SIGNS = frozenset((0, 3, 6, 9))


def _lilly_context_selection(
        default, allowed, context=None, context_key=None,
        unassessed=('unassessed', 'source_only')):
    selection = _lilly_context_choice(
        default, set(allowed), context=context, context_key=context_key,
    )
    if selection is None or selection['value'] in set(unassessed):
        return None
    return selection


def _lilly_current_relation_witness(
        chrt, actor, target, aspects, route):
    if actor is None or target is None or actor == target:
        return None
    rows = tuple(_body_aspect_matches(
        chrt, actor, target, tuple(aspects), orb=None,
        orb_policy='lilly_moiety', aspect_frame='degree',
    ))
    if not rows:
        return None
    return {
        'route': route, 'actor_pid': int(actor), 'target_pid': int(target),
        'relation': dict(rows[0]), 'pids': (int(actor), int(target)),
    }


def _lilly_house_cusp_ray_witness(
        chrt, pid, house, aspects, route,
        house_frame='regiomontanus_5deg'):
    cusp = _house_cusp_lon(chrt, int(house), house_frame)
    rows = tuple(_longitude_aspect_matches(
        chrt, (pid,), cusp, f'H{int(house)} cusp', tuple(aspects),
        None, 'lilly_moiety', 'degree', endpoint_kind='house_cusp',
    )) if cusp is not None else ()
    if not rows:
        return None
    return {
        'route': route, 'pids': (int(pid),), 'house': int(house),
        'point_relation': dict(rows[0]), 'cusp_longitude': float(cusp),
        'house_frame': str(house_frame),
    }


def _lilly_node_house(chrt, role, house_frame='regiomontanus_5deg'):
    longitude = (
        _north_node_lon(chrt) if str(role) == 'north_node'
        else _south_node_lon(chrt) if str(role) == 'south_node'
        else None
    )
    if longitude is None:
        return None
    return _house_of_frame(chrt, longitude, house_frame)


def _lilly_body_in_source_house(
        chrt, pid, house, house_frame='regiomontanus_5deg'):
    return _lilly_body_house(chrt, pid, house_frame) == int(house)


def _lilly_planet_cadent_from_own_place(
        chrt, pid, reading='zodiacal_from_domicile_or_exaltation',
        context=None,
        context_key='pregnancy_cadent_own_definition',
        house_frame='regiomontanus_5deg'):
    selection = _lilly_context_selection(
        reading,
        {'source_only', 'radix_cadent_houses',
         'zodiacal_from_domicile_or_exaltation'},
        context=context, context_key=context_key,
    )
    if selection is None:
        return None
    body = _planet(chrt, pid)
    longitude = _lon(body) if body is not None else None
    if longitude is None:
        return None
    if selection['value'] == 'radix_cadent_houses':
        cadent = _lilly_body_house(
            chrt, pid, house_frame) in (3, 6, 9, 12)
    else:
        anchors = set(_DOMICILE.get(pid, ()))
        anchors.update(
            sign for sign in range(12)
            if _exaltation_ruler_at(
                chrt, sign, dignity_frame='lilly') == pid
        )
        sign = _sign(longitude)
        cadent = any((sign - anchor) % 12 in (2, 5, 8, 11)
                     for anchor in anchors)
    return {
        'cadent': bool(cadent), 'reading': selection,
        'pid': int(pid), 'sign': _sign(longitude),
        'house_frame': str(house_frame),
    }


