def _lilly_pregnancy_birth_light_event(
        chrt, context=None, question_type='unassessed',
        question_context_key='pregnancy_question_type'):
    question = _lilly_pregnancy_question(
        question_type, context=context, context_key=question_context_key,
    )
    if question is None or question['value'] not in (
            'current_pregnancy', 'known_pregnancy'):
        return None
    actors = [
        ('ascendant', None, _point_lon(chrt, 'ASC')),
        ('lord_1', _lord_of_house(chrt, 1), None),
        ('moon', astrology.SE_MOON, None),
        ('lord_5', _lord_of_house(chrt, 5), None),
        ('h5_cusp', None, _house_cusp_lon(chrt, 5)),
    ]
    for pid in _PLANET_IDS.values():
        if _lilly_body_house(chrt, pid) == 1:
            actors.append(('ascendant_tenant', pid, None))
    votes = []
    for role, pid, explicit_lon in actors:
        body = _planet(chrt, pid) if pid is not None else None
        longitude = explicit_lon if explicit_lon is not None else (
            _lon(body) if body is not None else None
        )
        if longitude is None:
            continue
        vote = 'day' if _sign(longitude) in _MASCULINE_SIGNS else 'night'
        votes.append({
            'role': role, 'pid': pid, 'longitude': float(longitude),
            'sign': _sign(longitude), 'vote': vote,
        })
    if not votes:
        return None
    day = sum(row['vote'] == 'day' for row in votes)
    night = len(votes) - day
    strongest = None
    if day == night:
        ranked = []
        for row in votes:
            if row['pid'] is None:
                continue
            state = _lilly_fortitude_event(chrt, row['pid'])
            if state.get('complete'):
                ranked.append((int(state['net']), row))
        if ranked:
            best = max(value for value, _row in ranked)
            leaders = [row for value, row in ranked if value == best]
            if len(leaders) == 1:
                strongest = leaders[0]
                if strongest['vote'] == 'day':
                    day += 1
                else:
                    night += 1
    outcome = 'day' if day > night else 'night' if night > day else 'twilight'
    return {
        'outcome': outcome, 'dimension': 'birth_light',
        'votes': tuple(votes), 'counts': {'day': day, 'night': night},
        'strongest_tiebreak': strongest, 'question': question,
    }


