# Translation and collection of light (horary perfection paths 2 & 3)
# ─────────────────────────────────────────────────────────────

_LILLY_TREASURE_CONTEXT_KEY = 'treasure_significator'


def resolve_lilly_treasure_significator(chrt, context=None):
    """Resolve Lilly's selected treasure planet from question context.

    The inspector supplies exactly one of ``lord_4`` or a named classical
    body. Missing, ``unspecified``, non-string, and unknown values never
    fall back to L4: acquisition predicates fail closed until the user has
    made a valid selection.
    """
    raw = (context or {}).get(_LILLY_TREASURE_CONTEXT_KEY)
    event = {
        'status': 'unavailable',
        'branch': 'missing_selection',
        'context_key': _LILLY_TREASURE_CONTEXT_KEY,
        'raw_selection': raw,
        'selection': None,
        'significator_pid': None,
        'candidate_pids': (),
        'source_house': None,
    }
    if not isinstance(raw, str):
        return event
    selection = raw.strip().lower().replace('-', '_')
    event['selection'] = selection
    if selection in ('', 'unspecified'):
        event['branch'] = 'unspecified_selection'
        return event
    if selection == 'lord_4':
        pid = _lord_of_house(chrt, 4)
        branch = 'lord_4'
        source_house = 4
    elif selection in _PLANET_IDS:
        pid = _PLANET_IDS[selection]
        branch = 'named_classical_body'
        source_house = None
    else:
        event['status'] = 'invalid'
        event['branch'] = 'invalid_selection'
        return event
    if (pid not in _PLANET_IDS.values() or _planet(chrt, pid) is None):
        event.update({
            'branch': f'{branch}_unavailable',
            'source_house': source_house,
        })
        return event
    event.update({
        'status': 'resolved',
        'branch': branch,
        'significator_pid': int(pid),
        'candidate_pids': (int(pid),),
        'source_house': source_house,
    })
    return event


_LILLY_QUADRANT_BY_HOUSE = {
    10: 'east', 11: 'east', 12: 'east',
    7: 'south', 8: 'south', 9: 'south',
    4: 'west', 5: 'west', 6: 'west',
    1: 'north', 2: 'north', 3: 'north',
}
_LILLY_QUADRANT_ORDER = ('east', 'south', 'west', 'north')
_LILLY_SIGN_DIRECTION = {
    0: 'east', 4: 'east', 8: 'east',       # fire
    1: 'south', 5: 'south', 9: 'south',    # earth
    2: 'west', 6: 'west', 10: 'west',      # air
    3: 'north', 7: 'north', 11: 'north',   # water
}


def _lilly_short_journey_direction_event(
        chrt, context=None, reading='strongest_significator',
        reading_context_key='short_journey_direction_reading',
        house_frame='regiomontanus_5deg', dignity_frame='lilly', **_):
    """Keep Lilly's H3-cusp, L3, and Moon direction witnesses together.

    The text names all three places and explicitly says to judge by the
    strongest significator. ``strongest_significator`` compares Lord 3 and
    Moon by the source's essential-dignity table; equal scores remain visible.
    ``all_witnesses`` remains a diagnostic view, and ``source_only`` fails
    closed.
    """
    selected = str(reading or 'strongest_significator').strip().lower().replace(
        '-', '_',
    )
    if reading_context_key:
        raw = (context or {}).get(reading_context_key, selected)
        if not isinstance(raw, str):
            return {'status': 'invalid', 'reading': None, 'witnesses': ()}
        selected = raw.strip().lower().replace('-', '_')
    if selected not in {
            'all_witnesses', 'strongest_significator', 'source_only'}:
        return {'status': 'invalid', 'reading': selected, 'witnesses': ()}
    if selected == 'source_only':
        return {
            'status': 'source_only', 'reading': selected, 'witnesses': (),
            'selected_direction': None, 'tied_directions': (),
        }
    cusp = _house_cusp_lon(chrt, 3, house_frame)
    lord_3 = _lord_of_house(chrt, 3)
    moon = astrology.SE_MOON
    lord_body = _planet(chrt, lord_3) if lord_3 is not None else None
    moon_body = _planet(chrt, moon)
    lord_lon = _lon(lord_body) if lord_body is not None else None
    moon_lon = _lon(moon_body) if moon_body is not None else None
    if cusp is None or lord_lon is None or moon_lon is None:
        return {
            'status': 'unresolved', 'reading': selected, 'witnesses': (),
            'selected_direction': None, 'tied_directions': (),
        }

    def essential(pid):
        event = _lilly_fortitude_event(chrt, pid)
        factors = dict(event.get('essential_factors') or {})
        return {
            'score': int(event.get('essential_total', 0)),
            'factors': factors,
            # Essential-table completeness does not depend on fixed-star or
            # accidental data used by the complete fortitude tally.
            'complete': bool(
                _selected_dignity_tables(chrt, dignity_frame) is not None
                and _planet(chrt, pid) is not None
            ),
        }

    l3_strength = essential(lord_3)
    moon_strength = essential(moon)
    witnesses = (
        {
            'role': 'h3_cusp_sign', 'pid': None,
            'longitude': float(cusp), 'sign': _sign(cusp),
            'direction': _LILLY_SIGN_DIRECTION[_sign(cusp)],
            'strength': None,
        }, {
            'role': 'lord_3_sign', 'pid': int(lord_3),
            'longitude': float(lord_lon), 'sign': _sign(lord_lon),
            'direction': _LILLY_SIGN_DIRECTION[_sign(lord_lon)],
            'strength': l3_strength,
        }, {
            'role': 'moon_sign', 'pid': moon,
            'longitude': float(moon_lon), 'sign': _sign(moon_lon),
            'direction': _LILLY_SIGN_DIRECTION[_sign(moon_lon)],
            'strength': moon_strength,
        },
    )
    result = {
        'status': 'resolved', 'reading': selected,
        'witnesses': witnesses, 'selected_direction': None,
        'selected_roles': (), 'tied_directions': (),
        'selection_basis': 'source_witnesses_no_consensus',
        'house_frame': str(house_frame),
        'dignity_frame': str(dignity_frame),
    }
    if selected == 'all_witnesses':
        return result
    if not (l3_strength['complete'] and moon_strength['complete']):
        result['status'] = 'unresolved'
        result['selection_basis'] = 'essential_strength_incomplete'
        return result
    maximum = max(l3_strength['score'], moon_strength['score'])
    leaders = tuple(
        row for row in witnesses[1:]
        if row['strength']['score'] == maximum
    )
    directions = tuple(dict.fromkeys(row['direction'] for row in leaders))
    if len(directions) != 1:
        result.update({
            'status': 'tie', 'tied_directions': directions,
            'selected_roles': tuple(row['role'] for row in leaders),
            'selection_basis': 'equal_essential_strength',
        })
        return result
    result.update({
        'selected_direction': directions[0],
        'selected_roles': tuple(row['role'] for row in leaders),
        'selection_basis': 'strongest_essential_significator',
    })
    return result


def lilly_short_journey_direction(
        chrt, context=None, reading='strongest_significator',
        reading_context_key='short_journey_direction_reading',
        house_frame='regiomontanus_5deg', dignity_frame='lilly', **kwargs):
    return _lilly_short_journey_direction_event(
        chrt, context=context, reading=reading,
        reading_context_key=reading_context_key,
        house_frame=house_frame, dignity_frame=dignity_frame,
        **kwargs,
    ).get('status') in ('resolved', 'tie')


def lilly_journey_direction_event(
        chrt, house_frame='profile', dignity_frame='lilly', **_):
    """Resolve Lilly's best journey quadrant and separate avoid quarters."""
    benefic_witnesses = []
    counts = {quadrant: 0 for quadrant in _LILLY_QUADRANT_ORDER}
    strengths = {quadrant: 0 for quadrant in _LILLY_QUADRANT_ORDER}
    missing = []
    with semantic_scope({
            'house_frame': house_frame, 'dignity_frame': dignity_frame}):
        for role, pid in (
                ('jupiter', astrology.SE_JUPITER),
                ('venus', astrology.SE_VENUS)):
            body = _planet(chrt, pid)
            longitude = _lon(body) if body is not None else None
            house = (
                _house_of_frame(chrt, longitude, house_frame)
                if longitude is not None else None
            )
            fortitude = _lilly_fortitude_event(chrt, pid)
            if (house not in _LILLY_QUADRANT_BY_HOUSE
                    or not fortitude or not fortitude.get('complete')
                    or fortitude.get('net') is None):
                missing.append(role)
                continue
            quadrant = _LILLY_QUADRANT_BY_HOUSE[house]
            strength = int(fortitude['net'])
            counts[quadrant] += 1
            strengths[quadrant] += strength
            benefic_witnesses.append({
                'role': role, 'pid': int(pid),
                'longitude': float(longitude) % 360.0,
                'house': int(house), 'quadrant': quadrant,
                'fortitude': fortitude, 'strength': strength,
            })

        infortune_witnesses = []
        infortune_rows = (
            ('mars', astrology.SE_MARS, None),
            ('saturn', astrology.SE_SATURN, None),
            ('south_node', None, _south_node_lon(chrt)),
        )
        for role, pid, supplied_lon in infortune_rows:
            body = _planet(chrt, pid) if pid is not None else None
            longitude = (
                supplied_lon if pid is None
                else _lon(body) if body is not None else None
            )
            house = (
                _house_of_frame(chrt, longitude, house_frame)
                if longitude is not None else None
            )
            if house not in _LILLY_QUADRANT_BY_HOUSE:
                continue
            infortune_witnesses.append({
                'role': role, 'pid': pid,
                'longitude': float(longitude) % 360.0,
                'house': int(house),
                'quadrant': _LILLY_QUADRANT_BY_HOUSE[house],
            })
    avoid_quadrants = tuple(dict.fromkeys(
        row['quadrant'] for row in infortune_witnesses
    ))
    base = {
        'status': 'unresolved', 'selected_quadrant': None,
        'selection_basis': None, 'benefic_counts': counts,
        'benefic_strengths': strengths, 'tied_quadrants': (),
        'benefic_witnesses': tuple(benefic_witnesses),
        'avoid_quadrants': avoid_quadrants,
        'infortune_witnesses': tuple(infortune_witnesses),
        'missing_roles': tuple(missing),
        'house_frame': str(house_frame).lower().replace('-', '_'),
        'dignity_frame': _effective_dignity_frame(dignity_frame),
    }
    if missing or len(benefic_witnesses) != 2:
        return base
    maximum_count = max(counts.values())
    count_leaders = tuple(
        quadrant for quadrant in _LILLY_QUADRANT_ORDER
        if counts[quadrant] == maximum_count
    )
    if len(count_leaders) == 1:
        selected = count_leaders[0]
        basis = 'benefic_count'
        tied = ()
    else:
        maximum_strength = max(strengths[value] for value in count_leaders)
        strength_leaders = tuple(
            quadrant for quadrant in count_leaders
            if strengths[quadrant] == maximum_strength
        )
        if len(strength_leaders) != 1:
            base['tied_quadrants'] = strength_leaders
            return base
        selected = strength_leaders[0]
        basis = 'fortitude'
        tied = ()
    base.update({
        'status': 'resolved', 'selected_quadrant': selected,
        'selection_basis': basis, 'tied_quadrants': tied,
    })
    return base


def lilly_journey_direction(chrt, **kwargs):
    return lilly_journey_direction_event(chrt, **kwargs).get(
        'status',
    ) == 'resolved'


def lilly_hidden_goods_location_event(
        chrt, house_frame='profile', dignity_frame='lilly', **_):
    """Return L2 and L4 location witnesses without inventing consensus."""
    witnesses = []
    with semantic_scope({
            'house_frame': house_frame, 'dignity_frame': dignity_frame}):
        for source_house in (2, 4):
            pid = _lord_of_house(chrt, source_house)
            body = _planet(chrt, pid) if pid is not None else None
            longitude = _lon(body) if body is not None else None
            cusp = _house_cusp_lon(chrt, source_house)
            figure_house = (
                _house_of_frame(chrt, longitude, house_frame)
                if longitude is not None else None
            )
            if (pid is None or longitude is None or cusp is None
                    or figure_house not in _LILLY_QUADRANT_BY_HOUSE):
                return {
                    'status': 'unresolved',
                    'witnesses': tuple(witnesses),
                    'missing_role': f'lord_{source_house}',
                }
            sign = _sign(longitude)
            cusp_sign = _sign(cusp)
            witnesses.append({
                'role': f'lord_{source_house}',
                'source_house': source_house, 'pid': int(pid),
                'longitude': float(longitude) % 360.0,
                'sign': sign, 'degree_in_sign': _deg_in_sign(longitude),
                'sign_direction': _LILLY_SIGN_DIRECTION[sign],
                'figure_house': int(figure_house),
                'quadrant': _LILLY_QUADRANT_BY_HOUSE[figure_house],
                'cusp_longitude': float(cusp) % 360.0,
                'cusp_sign': cusp_sign,
                'cusp_sign_direction': _LILLY_SIGN_DIRECTION[cusp_sign],
            })
    return {'status': 'resolved', 'witnesses': tuple(witnesses)}


def lilly_hidden_goods_location(chrt, **kwargs):
    return lilly_hidden_goods_location_event(chrt, **kwargs).get(
        'status',
    ) == 'resolved'


def lilly_treasure_depth_event(chrt, context=None, **_):
    """Exact selected-significator progress through its sign, without bins."""
    resolution = resolve_lilly_treasure_significator(chrt, context=context)
    result = {
        **resolution, 'status': 'unresolved',
        'longitude': None, 'sign': None, 'degree_in_sign': None,
    }
    if resolution.get('status') != 'resolved':
        return result
    pid = resolution.get('significator_pid')
    body = _planet(chrt, pid) if pid is not None else None
    longitude = _lon(body) if body is not None else None
    if longitude is None:
        return result
    result.update({
        'status': 'resolved', 'longitude': float(longitude) % 360.0,
        'sign': _sign(longitude),
        'degree_in_sign': _deg_in_sign(float(longitude) % 360.0),
    })
    return result


def lilly_treasure_depth(chrt, context=None, **kwargs):
    return lilly_treasure_depth_event(
        chrt, context=context, **kwargs,
    ).get('status') == 'resolved'


def _lilly_treasure_principals(chrt, context=None):
    event = resolve_lilly_treasure_significator(chrt, context=context)
    if event.get('status') != 'resolved':
        return None
    lord_1 = _lord_of_house(chrt, 1)
    if (lord_1 not in _PLANET_IDS.values()
            or _planet(chrt, lord_1) is None):
        return None
    result = dict(event)
    result.update({
        'lord_1_pid': int(lord_1),
        'role_pids': tuple(dict.fromkeys((
            int(event['significator_pid']), int(lord_1),
        ))),
        'role_collision': int(event['significator_pid']) == int(lord_1),
    })
    return result


def _lilly_treasure_mutual_reception_event(
        chrt, context=None,
        levels=('domicile', 'exaltation', 'triplicity', 'term', 'face'),
        dignity_frame='lilly'):
    event = _lilly_treasure_principals(chrt, context=context)
    if event is None or event['role_collision']:
        return None
    selected = event['significator_pid']
    lord_1 = event['lord_1_pid']
    wanted = {str(value).strip().lower() for value in tuple(levels)}
    if not wanted:
        return None
    with semantic_scope({'dignity_frame': dignity_frame}):
        selected_in_l1 = tuple(
            level for level in _reception_levels_of(chrt, selected, lord_1)
            if level in wanted
        )
        l1_in_selected = tuple(
            level for level in _reception_levels_of(chrt, lord_1, selected)
            if level in wanted
        )
    if not selected_in_l1 or not l1_in_selected:
        return None
    result = dict(event)
    result.update({
        'selected_received_by_l1': selected_in_l1,
        'l1_received_by_selected': l1_in_selected,
        'dignity_frame': _effective_dignity_frame(dignity_frame),
    })
    return result


def lilly_treasure_significator_mutual_reception_l1(
        chrt, context=None,
        levels=('domicile', 'exaltation', 'triplicity', 'term', 'face'),
        dignity_frame='lilly', **_):
    """Selected treasure planet and L1 receive one another."""
    return _lilly_treasure_mutual_reception_event(
        chrt, context=context, levels=levels,
        dignity_frame=dignity_frame,
    ) is not None


_CLASSICAL_PLANETS = (
    'moon', 'mercury', 'venus', 'mars', 'jupiter', 'saturn', 'sun',
)


def _linear_perfection_candidate(chrt, faster_pid, slower_pid, aspects, orb):
    """Current-motion estimate used to bound or safely fall back from search."""
    a = _planet(chrt, faster_pid)
    b = _planet(chrt, slower_pid)
    if a is None or b is None:
        return None
    la, lb = _lon(a), _lon(b)
    if la is None or lb is None:
        return None
    best = None
    rel = _speed(a) - _speed(b)
    for ang in tuple(aspects):
        if _aspect_direction(chrt, faster_pid, slower_pid, ang, orb) in ('applying', 'exact'):
            signed = _signed_orb(la, lb, ang)
            arc = abs(signed)
            if arc <= 1e-10:
                days = 0.0
            elif abs(rel) <= 1e-12:
                continue
            else:
                days = -signed / rel
                if days < 0.0:
                    continue
            if best is None or days < best[0]:
                best = (days, arc, ang)
    return best


def _corpus_motion_evaluator(chrt):
    """One lazy exact-motion evaluator per chart instance."""
    cached = getattr(chrt, '_corpus_motion_evaluator', None)
    if cached is not None:
        return cached
    # A lightweight/partial chart carries snapshot longitudes that need not
    # correspond to its placeholder JD.  Attaching a Swiss ephemeris evaluator
    # to such an object silently mixes two different charts and makes results
    # depend on whether another module happened to import the motion engine.
    # Full Aries charts always own both place and constructed house state.
    if not hasattr(chrt, 'place') or not hasattr(chrt, 'houses'):
        return None
    try:
        from engine.aspect_motion import ChartMotionEvaluator
        evaluator = ChartMotionEvaluator(chrt)
    except Exception:
        return None
    try:
        setattr(chrt, '_corpus_motion_evaluator', evaluator)
    except Exception:
        pass
    return evaluator


def _is_full_motion_chart(chrt):
    """Whether a chart is entitled to exact ephemeris event semantics.

    Linear motion is a deterministic compatibility seam for deliberately
    partial fixtures whose longitudes need not match their placeholder JD.
    A constructed Aries chart has the time/place/house context required by
    :class:`ChartMotionEvaluator`; if that exact path fails, substituting a
    tangent projection would manufacture chronology through possible turns.
    Such charts therefore fail closed instead of silently changing method.
    """
    return all(hasattr(chrt, attribute) for attribute in (
        'time', 'place', 'houses', 'options', 'planets',
    ))


def _exact_perfection_event(chrt, faster_pid, slower_pid, aspects,
                            horizon_days):
    """Search exact planetary motion and return perfection or first stop.

    The two traditional significators must perfect before either reaches a
    station or leaves its current sign.  This turns perfection into an event
    sequence instead of projecting the present relative speed indefinitely.
    ``None`` means exact search is unavailable and permits the conservative
    bounded fallback used by synthetic tests and partial charts.
    """
    evaluator = _corpus_motion_evaluator(chrt)
    if evaluator is None:
        return None
    try:
        from aries.astrology.transit_fast import api as transit_fast_api

        start = float(chrt.time.jd)
        end = start + max(1.0e-4, min(float(horizon_days), 4096.0))
        offsets = []
        angle_for_spec = []
        for raw_angle in tuple(aspects):
            angle = float(raw_angle) % 360.0
            candidates = (angle,) if angle in (0.0, 180.0) else (
                angle, (-angle) % 360.0,
            )
            for offset in candidates:
                if any(abs(offset - existing[2]) <= 1.0e-10
                       for existing in offsets):
                    continue
                offsets.append((0, 1, offset))
                angle_for_spec.append(float(raw_angle))
        hits = transit_fast_api.search_relative_aspects_batch_raw(
            [int(faster_pid), int(slower_pid)], start, end, offsets,
            context=evaluator.ephemeris_context,
        )
        exact_hits = [
            hit for hit in hits if float(hit[0]) >= start - 1.0e-8
        ]
        exact_hit = (
            min(exact_hits, key=lambda hit: float(hit[0]))
            if exact_hits else None
        )
        exact_jd = float(exact_hit[0]) if exact_hit is not None else None
        if exact_hit is not None:
            spec_index = int(exact_hit[1])
            angle = angle_for_spec[spec_index]
        else:
            # `_compute_perfection_event` currently narrows this call to the
            # one applying angle selected by the current-motion candidate.
            angle = float(tuple(aspects)[0])

        # An already exact relation is a current perfection.  Avoid creating
        # an empty blocker-search range around the anchor instant.
        if exact_jd is not None and exact_jd <= start + 1.0e-7:
            return {
                'status': 'perfects', 'stop_reason': None,
                'days': 0.0, 'arc': 0.0, 'angle': angle,
                'exact_jd': exact_jd, 'method': 'ephemeris',
            }

        blocker = None
        stop_search_jd = exact_jd if exact_jd is not None else end
        station_hits = transit_fast_api.search_station_times_batch(
            [int(faster_pid), int(slower_pid)], start + 1.0e-8,
            stop_search_jd + 1.0e-8,
            context=evaluator.ephemeris_context,
        )
        epsilon = 1.0e-7
        for hit in station_hits:
            jd = float(hit.jd_ut)
            # A station strictly before perfection refrains it.  At the same
            # instant the exact contact has already occurred and wins the tie.
            station_blocks = (
                jd <= stop_search_jd + epsilon if exact_jd is None
                else jd < exact_jd - epsilon
            )
            if station_blocks and (
                    blocker is None or jd < blocker[0]):
                blocker = (jd, 'station')

        for pid in (faster_pid, slower_pid):
            state = evaluator.planet(int(pid), start)
            if state is None:
                return None
            sign = int(float(state['longitude']) // 30.0) % 12
            boundaries = [sign * 30.0, ((sign + 1) % 12) * 30.0]
            crossings = transit_fast_api.search_year_transits(
                int(pid), start + 1.0e-8, stop_search_jd + 1.0e-8,
                boundaries, [0.0], context=evaluator.ephemeris_context,
            )
            for hit in crossings:
                jd = float(hit.jd_ut)
                # Leaving a sign is an exclusive perfection boundary: exact
                # on the ingress instant is outside the promised sign pair.
                if jd <= stop_search_jd + epsilon and (
                        blocker is None or jd < blocker[0]):
                    blocker = (jd, 'sign_ingress')

        if blocker is not None:
            return {
                'status': 'blocked',
                'stop_reason': blocker[1],
                'days': max(0.0, blocker[0] - start),
                'exact_days': (
                    max(0.0, exact_jd - start)
                    if exact_jd is not None else None
                ),
                'angle': angle,
                'method': 'ephemeris',
            }

        if exact_jd is None:
            # Exact search was available and completed, so a constant-motion
            # perfection must not be manufactured merely because no stopping
            # event was found inside this bounded horizon.  Fail closed while
            # retaining a diagnostic that distinguishes this from a partial
            # chart, for which `_compute_perfection_event` still uses its
            # documented bounded-linear fallback.
            return {
                'status': 'unresolved',
                'stop_reason': 'no_exact_event_within_horizon',
                'days': None, 'exact_days': None, 'angle': angle,
                'search_horizon_days': max(0.0, end - start),
                'method': 'ephemeris',
            }

        a0 = evaluator.planet(int(faster_pid), start)
        b0 = evaluator.planet(int(slower_pid), start)
        if a0 is None or b0 is None:
            return None
        arc = abs(_signed_orb(
            float(a0['longitude']), float(b0['longitude']), angle,
        ))
        return {
            'status': 'perfects', 'stop_reason': None,
            'days': max(0.0, exact_jd - start),
            'arc': arc, 'angle': angle, 'exact_jd': exact_jd,
            'method': 'ephemeris',
        }
    except Exception:
        return None


def _linear_sign_exit_days(lon, speed):
    """First constant-motion crossing of the current 30° sign boundary."""
    try:
        lon = float(lon) % 360.0
        speed = float(speed)
    except (TypeError, ValueError):
        return None
    if abs(speed) <= 1.0e-12:
        return None
    degree = lon % 30.0
    if speed > 0.0:
        distance = 30.0 - degree
        if distance <= 1.0e-10:
            distance = 30.0
    else:
        distance = degree
        if distance <= 1.0e-10:
            return 0.0
    return distance / abs(speed)


def _linear_station_days(chrt, pid, horizon_days):
    """Sample for a genuine speed-sign reversal in fallback mode."""
    initial = _speed_at(chrt, pid, 0.0)
    if initial is None:
        return None
    steps = max(2, min(512, int(float(horizon_days) / 0.25) + 1))
    previous = float(initial)
    previous_offset = 0.0
    for index in range(1, steps + 1):
        offset = float(horizon_days) * index / steps
        current = _speed_at(chrt, pid, offset)
        if current is None:
            return None
        current = float(current)
        if previous * current <= 0.0 and previous != current:
            fraction = abs(previous) / (abs(previous) + abs(current))
            return previous_offset + (offset - previous_offset) * fraction
        previous = current
        previous_offset = offset
    return None


def _compute_perfection_event(chrt, faster_pid, slower_pid, aspects, orb):
    """Return the next valid perfection or the earlier stopping event."""
    candidate = _linear_perfection_candidate(
        chrt, faster_pid, slower_pid, aspects, orb,
    )
    if candidate is None:
        return None
    linear_days, arc, angle = candidate
    exact = _exact_perfection_event(
        chrt, faster_pid, slower_pid, (angle,),
        max(2.0, linear_days * 1.5 + 2.0),
    )
    if exact is not None:
        return exact
    if _is_full_motion_chart(chrt):
        return None

    a = _planet(chrt, faster_pid)
    b = _planet(chrt, slower_pid)
    blockers = []
    for body in (a, b):
        exit_days = _linear_sign_exit_days(_lon(body), _speed(body))
        if exit_days is not None and exit_days <= linear_days + 1.0e-10:
            blockers.append((exit_days, 'sign_ingress'))
    for pid in (faster_pid, slower_pid):
        station_days = _linear_station_days(chrt, pid, linear_days)
        if (station_days is not None
                and station_days < linear_days - 1.0e-10):
            blockers.append((station_days, 'station'))
    if blockers:
        stop_days, reason = min(blockers, key=lambda item: item[0])
        return {
            'status': 'blocked', 'stop_reason': reason,
            'days': stop_days, 'exact_days': linear_days, 'angle': angle,
            'method': 'bounded-linear',
        }
    return {
        'status': 'perfects', 'stop_reason': None,
        'days': linear_days, 'arc': arc, 'angle': angle,
        'method': 'bounded-linear',
    }


def _perfection_event(chrt, faster_pid, slower_pid, aspects, orb):
    """Cached event sequence for one immutable chart/profile evaluation."""
    policy = _SEMANTIC_POLICY.get()
    try:
        chart_jd = round(float(chrt.time.jd), 10)
    except Exception:
        chart_jd = None
    faster_body = _planet(chrt, faster_pid)
    slower_body = _planet(chrt, slower_pid)
    try:
        state_signature = tuple(
            round(float(value), 9)
            for value in (
                _lon(faster_body), _speed(faster_body),
                _lon(slower_body), _speed(slower_body),
            )
        )
    except (TypeError, ValueError):
        state_signature = ()
    aspect_values = tuple(float(value) for value in tuple(aspects))
    effective_orbs = []
    for angle in aspect_values:
        limit, label = _body_orb_limit(
            chrt, faster_pid, slower_pid, angle, orb,
            policy.get('orb_policy'),
        )
        effective_orbs.append((
            angle,
            None if limit is None else round(float(limit), 9),
            str(label),
        ))
    key = (
        chart_jd,
        state_signature,
        int(faster_pid), int(slower_pid),
        aspect_values,
        None if orb is None else float(orb),
        str(policy.get('aspect_frame', 'degree')),
        str(policy.get('orb_policy', 'configured')),
        tuple(effective_orbs),
    )
    cache = getattr(chrt, '_corpus_perfection_cache', None)
    if cache is None:
        cache = {}
        try:
            setattr(chrt, '_corpus_perfection_cache', cache)
        except Exception:
            cache = None
    if cache is not None and key in cache:
        return cache[key]
    event = _compute_perfection_event(
        chrt, faster_pid, slower_pid, aspects, orb,
    )
    if cache is not None and event and event.get('method') == 'ephemeris':
        cache[key] = event
    return event


def _arc_to_perfection(chrt, faster_pid, slower_pid, aspects, orb):
    """Compatibility tuple for a perfection that survives station/ingress."""
    state = _body_relation_state(
        chrt, faster_pid, slower_pid, aspects=aspects, orb=orb,
        directions=('applying', 'exact'), boundary='pair_signs',
    )
    event = state.get('perfection')
    if not state.get('matched') or not isinstance(event, dict):
        return None
    return (event['days'], event['arc'], event['angle'])


def frustration(chrt, faster='moon', slower='saturn',
                 aspects=(0, 60, 90, 120, 180), orb=8.0,
                 boundary='pair_signs', **_):
    """The faster is applying to the slower, but before perfection the
    slower itself perfects a closer-orb aspect with a third planet —
    the swift is **frustrated**, the slow is **frustrater**.

    Lilly CA I Ch.XXVI: *"Frustration is when a swift Planet would come
    to the Conjunction or Aspect of a slower planet, but before he can
    come to it, the slower is joyned to another, and so doth frustrate
    the swift."*
    """
    pa = _pid(faster); pb = _pid(slower)
    if pa is None or pb is None or pa == pb:
        return False
    principal_state = _body_relation_state(
        chrt, pa, pb, aspects=aspects, directions=('applying', 'exact'),
        boundary=boundary, orb=orb, required_applicator_pid=pa,
    )
    principal = principal_state.get('perfection')
    if not principal_state.get('matched') or not isinstance(principal, dict):
        return False
    time_ab = float(principal['days'])
    for cname in _CLASSICAL_PLANETS:
        pc = _pid(cname)
        if pc in (pa, pb):
            continue
        # B perfects with C before A can perfect with B.
        competing = _next_perfected_aspect_event(
            chrt, pb, (pc,), aspects=aspects, boundary='none',
            require_current_application=False, orb=orb,
            horizon_days=max(1.0e-4, time_ab),
        )
        if (competing is not None
                and competing.get('status') == 'perfects'
                and float(competing['days']) < time_ab - 1.0e-8):
            return True
    return False


def prohibition(chrt, faster='moon', slower='saturn',
                 aspects=(0, 60, 90, 120, 180), orb=8.0,
                 boundary='pair_signs', **_):
    """A and B applying; a third planet C reaches A *or* B by aspect first
    (with smaller arc), interposing.

    Lilly CA I Ch.XXVI: *"Prohibition, when two Planets would come to a
    corporal Conjunction or Aspect, but before they can come to it, a
    third Planet doth interpose, by his Body or Aspect, so that he
    hindereth their Conjunction or Aspect."*
    """
    pa = _pid(faster); pb = _pid(slower)
    if pa is None or pb is None or pa == pb:
        return False
    principal_state = _body_relation_state(
        chrt, pa, pb, aspects=aspects, directions=('applying', 'exact'),
        boundary=boundary, orb=orb, required_applicator_pid=pa,
    )
    principal = principal_state.get('perfection')
    if not principal_state.get('matched') or not isinstance(principal, dict):
        return False
    time_ab = float(principal['days'])
    for cname in _CLASSICAL_PLANETS:
        pc = _pid(cname)
        if pc in (pa, pb):
            continue
        # Lilly's examples require the interposer to contact both
        # principals before their own partile aspect, not merely touch one.
        first = _next_perfected_aspect_event(
            chrt, pc, (pa,), aspects=aspects, boundary='none',
            require_current_application=False, orb=orb,
            horizon_days=max(1.0e-4, time_ab),
        )
        second = _next_perfected_aspect_event(
            chrt, pc, (pb,), aspects=aspects, boundary='none',
            require_current_application=False, orb=orb,
            horizon_days=max(1.0e-4, time_ab),
        )
        if (first is not None and second is not None
                and first.get('status') == 'perfects'
                and second.get('status') == 'perfects'
                and max(float(first['days']), float(second['days']))
                < time_ab - 1.0e-8):
            return True
    return False


def refranation(chrt, faster='moon', slower='saturn',
                 aspects=(0, 60, 90, 120, 180), orb=8.0,
                 boundary='pair_signs', **_):
    """A and B apply, but one actually reaches a station before perfection.

    Lilly CA I Ch.XXVI: *"Refrenation, when two Planets are applying
    together, before they come to perfect Conjunction or Aspect, one or
    both turn retrograde. The application is unprofitable."*  Now also
    The ephemeris is sampled through the projected perfection time. Present
    retrogradation or a merely slow planet is not sufficient: the turn must
    intervene before the exact aspect, matching Lilly's sequence clause.
    """
    pa = _pid(faster); pb = _pid(slower)
    if pa is None or pb is None or pa == pb:
        return False
    state = _body_relation_state(
        chrt, pa, pb, aspects=aspects, directions=('applying', 'exact'),
        boundary=boundary, orb=orb, required_applicator_pid=pa,
    )
    event = state.get('perfection')
    return bool(
        isinstance(event, dict) and state.get('status') == 'blocked'
        and event.get('stop_reason') == 'station'
    )


_DIURNAL_PLANETS = {astrology.SE_SUN, astrology.SE_JUPITER, astrology.SE_SATURN}
_NOCTURNAL_PLANETS = {astrology.SE_MOON, astrology.SE_VENUS, astrology.SE_MARS}
_MASCULINE_SIGNS = {0, 2, 4, 6, 8, 10}  # Aries, Gem, Leo, Lib, Sag, Aqu


def _is_chart_daytime(chrt):
    try:
        return bool(chrt.planets.planets[astrology.SE_SUN].abovehorizon)
    except Exception:
        return True


def _planet_sect(chrt, pid):
    """'diurnal' or 'nocturnal' or None. Mercury is diurnal when oriental
    of the Sun, nocturnal when occidental — checked via the sign of
    `(sun_lon - merc_lon) mod 360`."""
    if pid in _DIURNAL_PLANETS:
        return 'diurnal'
    if pid in _NOCTURNAL_PLANETS:
        return 'nocturnal'
    if pid == astrology.SE_MERCURY:
        try:
            slon = chrt.planets.planets[astrology.SE_SUN].data[planets.Planet.LONG]
            mlon = chrt.planets.planets[astrology.SE_MERCURY].data[planets.Planet.LONG]
            d = (slon - mlon) % 360.0
            return 'diurnal' if d < 180.0 else 'nocturnal'
        except Exception:
            return 'diurnal'
    return None


def body_in_hayz(chrt, body='moon', **_):
    """Body is in Hayz — Lilly's three-way alignment of sect, hemisphere,
    and sign gender.

    CA I Ch.XV "+1" accidental dignity. Diurnal planets (Sun, Jupiter,
    Saturn) are in Hayz when in a **day chart**, **above the horizon**,
    in a **masculine sign**. Nocturnal planets (Moon, Venus, Mars) are
    in Hayz when in a **night chart**, **below the horizon**, in a
    **feminine sign**. Mercury inherits its sect from oriental/occidental
    relation to the Sun.
    """
    pid = _pid(body)
    if pid is None:
        return False
    sect = _planet_sect(chrt, pid)
    if sect is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    daytime = _is_chart_daytime(chrt)
    above = bool(getattr(p, 'abovehorizon', False))
    sign_idx = _sign(_lon(p))
    masculine = sign_idx in _MASCULINE_SIGNS
    if sect == 'diurnal':
        return daytime and above and masculine
    return (not daytime) and (not above) and (not masculine)


def _fixed_star_lon(chrt, star):
    """Loaded fixed-star longitude by canonical display name."""
    target = str(star or '').strip().lower()
    if not target:
        return None
    try:
        for entry in chrt.fixstars.data:
            if str(entry[0]).strip().lower() == target:
                return float(entry[2])
    except Exception:
        return None
    return None


def _fixed_star_contact_matches(chrt, pid, star, orb=None,
                                point_orb_policy='profile',
                                point_frame='profile',
                                orb_policy='profile'):
    star_lon = _fixed_star_lon(chrt, star)
    if star_lon is None:
        return []
    selected = _effective_point_orb_policy(point_orb_policy, orb_policy)
    return _longitude_aspect_matches(
        chrt, (pid,), star_lon, str(star), (0,), orb, selected, point_frame,
        endpoint_kind='fixed_star',
    )


def body_near_fixed_star(chrt, body='moon', star='regulus', orb=None,
                         point_orb_policy='profile',
                         point_frame='profile', orb_policy='profile', **_):
    """Named body in a typed conjunction with a loaded fixed star.

    The allowance comes from the resolved point-contact doctrine.  A source
    number must use ``point_orb_policy='source_fixed'``; there is no hidden
    universal fixed-star radius.
    """
    pid = _pid(body)
    if pid is None:
        return False
    return bool(_fixed_star_contact_matches(
        chrt, pid, star, orb, point_orb_policy, point_frame, orb_policy,
    ))


def _body_between_bodies(chrt, pid, boundary_a, boundary_b):
    """Strict same-sign zodiacal enclosure by two bodily longitudes."""
    target = _planet(chrt, pid)
    left = _planet(chrt, boundary_a)
    right = _planet(chrt, boundary_b)
    if target is None or left is None or right is None:
        return False
    target_lon = _lon(target)
    left_lon = _lon(left)
    right_lon = _lon(right)
    if None in (target_lon, left_lon, right_lon):
        return False
    signs = {_sign(target_lon), _sign(left_lon), _sign(right_lon)}
    if len(signs) != 1:
        return False
    lower, upper = sorted((_deg_in_sign(left_lon), _deg_in_sign(right_lon)))
    return lower < _deg_in_sign(target_lon) < upper


def body_beleaguered(chrt, body='moon', **_):
    """Body strictly between Venus and Jupiter in one sign.

    This is retained as a general geometric primitive.  Lilly explicitly
    defines only besiegement by Mars and Saturn; a pack must not present the
    benefic counterpart as Lilly's doctrine without another source.
    """
    pid = _pid(body)
    if pid in (None, astrology.SE_VENUS, astrology.SE_JUPITER):
        return False
    return _body_between_bodies(
        chrt, pid, astrology.SE_VENUS, astrology.SE_JUPITER,
    )


def lord_of_house_cazimi(
        chrt, house=1, orb=0.283, context=None,
        solar_condition_profile='lilly_1647', **_):
    """Lord of `house` within 17' of the Sun. Lilly's "+5" cazimi."""
    house = _resolved_house_spec(house, context)
    if house is None:
        return False
    pid = _lord_of_house(chrt, house)
    if pid is None or pid == astrology.SE_SUN:
        return False
    selected = _effective_solar_condition_profile(
        chrt, solar_condition_profile,
    )
    if selected != solar_proximity.PROFILE_LILLY_1647:
        return _profiled_solar_phase(
            chrt, pid, solar_condition_profile,
        ) == 'cazimi'
    sun = _planet(chrt, astrology.SE_SUN)
    p = _planet(chrt, pid)
    if sun is None or p is None:
        return False
    sun_lon = _lon(sun)
    body_lon = _lon(p)
    return _ang_diff(sun_lon, body_lon) <= float(orb)


def lord_of_house_under_beams(
        chrt, house=1, combust_orb=8.5, beams_orb=17.0,
        context=None, solar_condition_profile='lilly_1647', **_):
    """Lord of `house` between combust orb and beams orb of Sun.
    Lilly's "−4" under the beams."""
    house = _resolved_house_spec(house, context)
    if house is None:
        return False
    pid = _lord_of_house(chrt, house)
    if pid is None or pid == astrology.SE_SUN:
        return False
    selected = _effective_solar_condition_profile(
        chrt, solar_condition_profile,
    )
    if selected != solar_proximity.PROFILE_LILLY_1647:
        return _profiled_solar_phase(
            chrt, pid, solar_condition_profile,
        ) == 'under_beams'
    sun = _planet(chrt, astrology.SE_SUN)
    p = _planet(chrt, pid)
    if sun is None or p is None:
        return False
    sun_lon = _lon(sun)
    body_lon = _lon(p)
    d = _ang_diff(sun_lon, body_lon)
    cazimi = d <= 17.0 / 60.0
    combust = (
        _sign(sun_lon) == _sign(body_lon)
        and d <= float(combust_orb)
    )
    return not cazimi and not combust and d <= float(beams_orb)


def lord_of_house_besieged(chrt, house=1, **_):
    """House lord strictly between Mars and Saturn in one sign."""
    pid = _lord_of_house(chrt, house)
    if pid is None or pid in (astrology.SE_MARS, astrology.SE_SATURN):
        return False
    return _body_between_bodies(
        chrt, pid, astrology.SE_MARS, astrology.SE_SATURN,
    )


def lord_of_house_beleaguered(chrt, house=1, **_):
    """House lord strictly between Venus and Jupiter in one sign."""
    pid = _lord_of_house(chrt, house)
    if pid is None or pid in (astrology.SE_VENUS, astrology.SE_JUPITER):
        return False
    return _body_between_bodies(
        chrt, pid, astrology.SE_VENUS, astrology.SE_JUPITER,
    )


def l1_received_by_any_lord(chrt, levels=('domicile', 'exaltation'), **_):
    """Lord of Asc is received by SOME other house's lord at one of the
    listed dignity levels. Lilly's universal "the querent has friends in
    the figure" observation — surfaces a key reception-chain testimony
    independent of question type.
    """
    pid_q = _lord_of_house(chrt, 1)
    if pid_q is None:
        return False
    target = set(str(l).lower() for l in levels)
    for h in range(2, 13):
        pid_h = _lord_of_house(chrt, h)
        if pid_h is None or pid_h == pid_q:
            continue
        found = _reception_levels_of(chrt, pid_q, pid_h)
        if any(lvl in target for lvl in found):
            return True
    return False


def _dispositor_terminus(chrt, start_pid, max_iter=15):
    """Follow the dispositor chain starting at `start_pid`. Each step:
    look at the planet's current sign, find that sign's domicile ruler,
    set ruler as next step. Continue until we hit a planet that rules
    its own sign (terminal) or detect a cycle.

    Returns the terminal SE planet id, or None on cycle / failure.
    """
    if start_pid is None:
        return None
    seen = set()
    current = start_pid
    for _ in range(int(max_iter)):
        if current in seen:
            return None  # cycle without terminus
        seen.add(current)
        p = _planet(chrt, current)
        if p is None:
            return None
        ruler = _sign_ruler_at(chrt, _sign(_lon(p)))
        if ruler is None or ruler == current:
            return current
        current = ruler
    return None


def dispositor_chain_terminus_is(chrt, start_house=1, body='mars', **_):
    """The dispositor chain starting at the lord of `start_house` ends at
    the named body (i.e., the named body rules its own sign and is the
    final dispositor of the chain).

    Lilly: "X hath final dominion over the matter" — the planet at the
    end of the chain governs all signification flowing through it.
    """
    start_pid = _lord_of_house(chrt, start_house)
    terminus = _dispositor_terminus(chrt, start_pid)
    target = _pid(body)
    return terminus is not None and target is not None and terminus == target


def dispositor_chain_terminus_class(chrt, start_house=1, class_='benefic', **_):
    """The dispositor chain terminus belongs to the named class.

    `class_` ∈ {'benefic','malefic','self'}. 'self' means the chain ends
    at the same planet it started (the starting significator rules its
    own sign — the querent is "his own master," self-contained).
    """
    start_pid = _lord_of_house(chrt, start_house)
    terminus = _dispositor_terminus(chrt, start_pid)
    if terminus is None:
        return False
    if class_ == 'benefic':
        return terminus in (astrology.SE_VENUS, astrology.SE_JUPITER)
    if class_ == 'malefic':
        return terminus in (astrology.SE_MARS, astrology.SE_SATURN)
    if class_ == 'self':
        return terminus == start_pid
    return False


def lords_perfect_with_reception(chrt, context=None, house_a=None, house_b=None,
                                   aspects=(0, 60, 90, 120, 180), orb=None,
                                   reception_levels=('domicile', 'exaltation'),
                                   directions=('applying', 'exact'),
                                   reception_mode='mutual',
                                   boundary='pair_signs', orb_policy=None,
                                   aspect_frame='profile',
                                   require_named_applicator=False, **_):
    """Lord of `house_a` perfects with lord of `house_b` by aspect AND
    the pair is in mutual reception by major dignity.

    Lilly's "with reception, best of all" — the strongest possible
    perfection. Even a square or opposition with mutual reception
    inclines to good outcome. House args accept literal ints OR context
    keys ('querent_house'/'quesited_house'/etc.) for use in any theme.
    """
    ha = _resolved_house_spec(house_a, context)
    hb = _resolved_house_spec(house_b, context)
    if ha is None or hb is None:
        return False
    pid_a = _lord_of_house(chrt, ha)
    pid_b = _lord_of_house(chrt, hb)
    if pid_a is None or pid_b is None or pid_a == pid_b:
        return False
    selected_directions = tuple(directions)
    if not _directional_relation_matches(
            chrt, pid_a, pid_b, aspects, orb, selected_directions,
            boundary, orb_policy, aspect_frame,
            pid_a if require_named_applicator else None):
        return False
    target = set(str(l).lower() for l in reception_levels)
    a_in_b = _reception_levels_of(chrt, pid_a, pid_b)
    b_in_a = _reception_levels_of(chrt, pid_b, pid_a)
    receives_a = any(lvl in target for lvl in a_in_b)
    receives_b = any(lvl in target for lvl in b_in_a)
    mode = str(reception_mode or 'mutual').lower().replace('-', '_')
    if mode in ('either', 'one_way', 'any'):
        return receives_a or receives_b
    if mode == 'mutual':
        return receives_a and receives_b
    return False


def lord_of_house_near_fixed_star(chrt, house=1, star='regulus', orb=None,
                                  point_orb_policy='profile',
                                  point_frame='profile',
                                  orb_policy='profile', **_):
    """House lord in a typed conjunction with a loaded fixed star."""
    pid = _lord_of_house(chrt, house)
    if pid is None:
        return False
    return bool(_fixed_star_contact_matches(
        chrt, pid, star, orb, point_orb_policy, point_frame, orb_policy,
    ))


def _almuten_of_topic_pid(chrt, topic):
    """SE planet id of the Almuten of the named topic. Reads
    `chrt.almutens.topicals.maxscore[i]` after locating `topic` in
    `chrt.almutens.topicals.names`. Returns None when topical-almuten
    table isn't configured (`options.topicals` defaults to None — must
    be enabled via the chart UI's Topicals dialog), the topic isn't in
    the loaded set, or there's a tie at max.
    """
    try:
        topicals = chrt.almutens.topicals
    except Exception:
        return None
    if topicals is None:
        return None
    target = str(topic).strip().lower()
    try:
        for i, n in enumerate(topicals.names):
            if str(n).strip().lower() == target:
                ms = topicals.maxscore[i]
                if ms[0] < 0 or ms[2]:
                    return None
                return int(ms[0])
    except Exception:
        return None
    return None


def almuten_of_topic_is(chrt, topic='marriage', body='venus', **_):
    """The Almuten of the named topic is the named body. Requires
    `options.topicals` configured; otherwise silently False.
    """
    target = _pid(body)
    am = _almuten_of_topic_pid(chrt, topic)
    return target is not None and am is not None and target == am


def almuten_of_topic_class(chrt, topic='marriage', class_='benefic', **_):
    """The Almuten of the named topic belongs to the given class. `class_`
    ∈ {'benefic','malefic'}. Requires `options.topicals` configured.
    """
    am = _almuten_of_topic_pid(chrt, topic)
    if am is None:
        return False
    if class_ == 'benefic':
        return am in (astrology.SE_VENUS, astrology.SE_JUPITER)
    if class_ == 'malefic':
        return am in (astrology.SE_MARS, astrology.SE_SATURN)
    return False


def lord_of_house_in_hayz(chrt, house=1, **_):
    """Lord of `house` is in its own Hayz (sect-aligned hemisphere AND
    sign gender)."""
    pid = _lord_of_house(chrt, house)
    if pid is None:
        return False
    sect = _planet_sect(chrt, pid)
    if sect is None:
        return False
    p = _planet(chrt, pid)
    if p is None:
        return False
    daytime = _is_chart_daytime(chrt)
    above = bool(getattr(p, 'abovehorizon', False))
    sign_idx = _sign(_lon(p))
    masculine = sign_idx in _MASCULINE_SIGNS
    if sect == 'diurnal':
        return daytime and above and masculine
    return (not daytime) and (not above) and (not masculine)


def body_besieged(chrt, body='moon', **_):
    """Body strictly between Mars and Saturn's bodies in one sign.

    Lilly CA I Ch.XV defines bodily enclosure and gives Saturn 15° Aries,
    Venus 13° Aries, Mars 10° Aries.  No 8° radius or aspect sequence is
    added to that definition.
    """
    pid = _pid(body)
    if pid in (None, astrology.SE_MARS, astrology.SE_SATURN):
        return False
    return _body_between_bodies(
        chrt, pid, astrology.SE_MARS, astrology.SE_SATURN,
    )


def moon_frustration_in_chart(chrt, aspects=(0, 60, 90, 120, 180), orb=8.0, **_):
    """The Moon is currently applying to a slower body, but that body
    perfects a closer aspect with a third first — the Moon's testimony
    is frustrated. Scans Moon vs each of the six other classical bodies."""
    for sname in _CLASSICAL_PLANETS:
        if sname == 'moon':
            continue
        if frustration(chrt, faster='moon', slower=sname, aspects=aspects, orb=orb):
            return True
    return False


def moon_prohibition_in_chart(chrt, aspects=(0, 60, 90, 120, 180), orb=8.0, **_):
    """The Moon is applying to some body, but a third planet interposes."""
    for sname in _CLASSICAL_PLANETS:
        if sname == 'moon':
            continue
        if prohibition(chrt, faster='moon', slower=sname, aspects=aspects, orb=orb):
            return True
    return False


def moon_refranation_in_chart(chrt, aspects=(0, 60, 90, 120, 180), orb=8.0, **_):
    """The Moon is applying to some body, but one of the pair is currently
    retrograde — application unprofitable."""
    for sname in _CLASSICAL_PLANETS:
        if sname == 'moon':
            continue
        if refranation(chrt, faster='moon', slower=sname, aspects=aspects, orb=orb):
            return True
    return False


def _faster_than_both(chrt, translator_pid, pid_a, pid_b):
    """The translator must be faster than both significators it carries light between."""
    t = _planet(chrt, translator_pid)
    a = _planet(chrt, pid_a); b = _planet(chrt, pid_b)
    if t is None or a is None or b is None:
        return False
    st = abs(_speed(t))
    return st > abs(_speed(a)) and st > abs(_speed(b))


_TRANSLATION_PRINCIPAL_ASPECTS = (0.0, 60.0, 120.0)


def _separating_angle(chrt, pid_a, pid_b, aspects, orb):
    """First authored aspect from which ``pid_a`` and ``pid_b`` separate."""
    for angle in tuple(aspects):
        if _aspect_direction(chrt, pid_a, pid_b, angle, orb) == 'separating':
            return float(angle)
    return None


def _translation_separation_event(chrt, translator_pid, first_lord,
                                  aspects, orb):
    """Exact past carrier contact that is still separating now."""
    separating_angle = _separating_angle(
        chrt, translator_pid, first_lord, aspects, orb,
    )
    if separating_angle is None:
        return None
    event = _last_perfected_aspect_event(
        chrt, translator_pid, (first_lord,),
        aspects=(separating_angle,), orb=orb, scope='within_orb',
    )
    if (event is None
            or event.get('phase') != 'separating'
            or abs(float(event.get('angle', math.inf))
                   - float(separating_angle)) > 1.0e-7):
        return None
    return event


def _earliest_direct_principal_event(chrt, lord_a, lord_b, aspects, orb):
    """First surviving direct soft perfection between two principals."""
    events = []
    for actor, target in ((lord_a, lord_b), (lord_b, lord_a)):
        event = _perfecting_event(chrt, actor, target, aspects, orb)
        if event is not None and event.get('status') == 'perfects':
            events.append(event)
    return min(events, key=lambda row: float(row['days'])) if events else None


def _perfecting_event(chrt, pid_a, pid_b, aspects, orb):
    """Next exact contact only when it survives station and sign ingress."""
    state = _body_relation_state(
        chrt, pid_a, pid_b, aspects, orb=orb,
        directions=('applying', 'exact'), boundary='pair_signs',
    )
    event = state.get('perfection')
    return dict(event) if state.get('matched') and event else None


def _lilly_treasure_perfection_event(
        chrt, context=None, aspects=(0, 60, 90, 120, 180), orb=6.0,
        directions=('applying', 'exact'), boundary='pair_signs',
        aspect_frame='degree', orb_policy='lilly_moiety'):
    principals = _lilly_treasure_principals(chrt, context=context)
    if principals is None or principals['role_collision']:
        return None
    selected = principals['significator_pid']
    lord_1 = principals['lord_1_pid']
    allowed = {
        str(value).strip().lower() for value in tuple(directions or ())
    }
    if (not allowed
            or not allowed.issubset({'applying', 'exact'})):
        return None
    semantic_args = {
        'aspect_frame': aspect_frame,
        'orb_policy': orb_policy,
    }
    with semantic_scope(semantic_args):
        state = _body_relation_state(
            chrt, selected, lord_1, aspects, orb=orb,
            orb_policy=orb_policy, aspect_frame=aspect_frame,
            directions=directions, boundary=boundary,
            required_applicator_pid=selected,
        )
        if not state.get('matched'):
            return None
        perfection = state.get('perfection')
    if perfection is None:
        return None
    result = dict(principals)
    result['perfection'] = dict(perfection)
    return result


def lilly_treasure_significator_perfects_l1(
        chrt, context=None, aspects=(0, 60, 90, 120, 180), orb=6.0,
        directions=('applying', 'exact'), boundary='pair_signs',
        aspect_frame='degree', orb_policy='lilly_moiety', **_):
    """Selected treasure planet reaches L1 before station or sign ingress."""
    return _lilly_treasure_perfection_event(
        chrt, context=context, aspects=aspects, orb=orb,
        directions=directions, boundary=boundary,
        aspect_frame=aspect_frame, orb_policy=orb_policy,
    ) is not None


def _linear_next_exact_contact(chrt, pid_a, pid_b, aspects, horizon_days):
    """Constant-motion fallback for an exact contact inside a time window."""
    a = _planet(chrt, pid_a)
    b = _planet(chrt, pid_b)
    if a is None or b is None:
        return None
    lon_a = _lon(a)
    lon_b = _lon(b)
    if lon_a is None or lon_b is None:
        return None
    speed = _speed(a) - _speed(b)
    relative_now = lon_a - lon_b
    best = None
    for raw_angle in tuple(aspects):
        angle = float(raw_angle) % 360.0
        targets = (angle,) if angle in (0.0, 180.0) else (
            angle, (-angle) % 360.0,
        )
        for target in targets:
            for revolution in range(-2, 3):
                exact_relative = target + 360.0 * revolution
                delta = exact_relative - relative_now
                if abs(speed) <= 1.0e-12:
                    if abs(delta) > 1.0e-10:
                        continue
                    days = 0.0
                else:
                    days = delta / speed
                if not -1.0e-9 <= days <= float(horizon_days) + 1.0e-9:
                    continue
                candidate = {
                    'status': 'perfects', 'days': max(0.0, days),
                    'angle': float(raw_angle), 'method': 'linear-contact',
                }
                if best is None or candidate['days'] < best['days']:
                    best = candidate
    return best


def _next_exact_contact(chrt, pid_a, pid_b, aspects, horizon_days):
    """First physical exact aspect, independent of present orb/application.

    Lilly's translation clause says the carrier must reach the target before
    *meeting* any other planet.  That is an event-order question, not a test
    of whether the competing contact is already inside its moiety.
    """
    evaluator = _corpus_motion_evaluator(chrt)
    if evaluator is not None:
        try:
            from aries.astrology.transit_fast import api as transit_fast_api

            start = float(chrt.time.jd)
            end = start + max(1.0e-7, float(horizon_days))
            offsets = []
            angle_for_spec = []
            for raw_angle in tuple(aspects):
                angle = float(raw_angle) % 360.0
                candidates = (angle,) if angle in (0.0, 180.0) else (
                    angle, (-angle) % 360.0,
                )
                for offset in candidates:
                    if any(abs(offset - row[2]) <= 1.0e-10
                           for row in offsets):
                        continue
                    offsets.append((0, 1, offset))
                    angle_for_spec.append(float(raw_angle))
            hits = transit_fast_api.search_relative_aspects_batch_raw(
                [int(pid_a), int(pid_b)], start, end, offsets,
                context=evaluator.ephemeris_context,
            )
            valid = [
                hit for hit in hits
                if start - 1.0e-8 <= float(hit[0]) <= end + 1.0e-8
            ]
            if not valid:
                return None
            hit = min(valid, key=lambda row: float(row[0]))
            return {
                'status': 'perfects',
                'days': max(0.0, float(hit[0]) - start),
                'angle': angle_for_spec[int(hit[1])],
                'exact_jd': float(hit[0]), 'method': 'ephemeris-contact',
            }
        except Exception:
            if _is_full_motion_chart(chrt):
                return None
    elif _is_full_motion_chart(chrt):
        return None
    return _linear_next_exact_contact(
        chrt, pid_a, pid_b, tuple(aspects), horizon_days,
    )


def _earliest_other_contact(chrt, actor_pid, target_pid, aspects,
                            horizon_days):
    """Earliest exact contact made by ``actor_pid`` with another planet."""
    earliest = None
    for other_name in _CLASSICAL_PLANETS:
        other_pid = _pid(other_name)
        if other_pid in (actor_pid, target_pid):
            continue
        event = _next_exact_contact(
            chrt, actor_pid, other_pid, tuple(aspects), horizon_days,
        )
        if event is None:
            continue
        if earliest is None or event['days'] < earliest['event']['days']:
            earliest = {'pid': other_pid, 'event': event}
    return earliest


def _translation_witness(chrt, context=None, from_house=None, to_house=None,
                         orb=6.0, aspects=(0, 60, 90, 120, 180),
                         reception_levels=('domicile', 'triplicity', 'term'),
                         require_reception=True, translator=None,
                         direction='either', principal_pids=None,
                         principal_labels=None, house_frame='profile'):
    """Return the complete Lilly translation sequence, or ``None``.

    This is intentionally one shared witness for Boolean evaluation and
    evidence rendering.  A valid translator must separate exactly from the
    first principal, be received there when the authored clause requires it,
    and perfect with the second before another carrier contact.  A direct
    principal perfection that occurs first makes translation non-causal.
    """
    if principal_pids is not None:
        try:
            pids = tuple(principal_pids)
        except TypeError:
            return None
        if len(pids) != 2:
            return None
        lord_a, lord_b = pids
        if (lord_a not in _PLANET_IDS.values()
                or lord_b not in _PLANET_IDS.values()):
            return None
        fh = from_house
        th = to_house
    else:
        fh = (
            from_house if from_house is not None
            else (context or {}).get('querent_house')
        )
        th = (
            to_house if to_house is not None
            else (context or {}).get('quesited_house')
        )
        if fh is None or th is None:
            return None
        lord_a = _lord_of_house(chrt, fh, house_frame)
        lord_b = _lord_of_house(chrt, th, house_frame)
    if (lord_a is None or lord_b is None or lord_a == lord_b
            or _planet(chrt, lord_a) is None
            or _planet(chrt, lord_b) is None):
        return None
    if principal_labels is None:
        labels = (
            f'L{int(fh)}' if fh is not None else planet_name_from_id(lord_a),
            f'L{int(th)}' if th is not None else planet_name_from_id(lord_b),
        )
    else:
        try:
            labels = tuple(str(value) for value in principal_labels)
        except TypeError:
            return None
        if len(labels) != 2:
            return None

    aspect_list = tuple(aspects)
    reception_target = {
        str(level).lower() for level in tuple(reception_levels)
    }
    requested_translator = _pid(translator) if translator is not None else None
    if translator is not None and requested_translator is None:
        return None
    translator_pids = (
        (requested_translator,)
        if requested_translator is not None
        else tuple(_pid(name) for name in _CLASSICAL_PLANETS)
    )
    selected_direction = str(direction or 'either').lower().replace('-', '_')
    if selected_direction in ('from_to', 'ordered', 'forward'):
        principal_orders = ((lord_a, lord_b),)
    elif selected_direction in ('to_from', 'reverse'):
        principal_orders = ((lord_b, lord_a),)
    elif selected_direction in ('either', 'any', 'bidirectional'):
        principal_orders = ((lord_a, lord_b), (lord_b, lord_a))
    else:
        return None
    for trans_pid in translator_pids:
        if trans_pid in (lord_a, lord_b):
            continue
        if not _faster_than_both(chrt, trans_pid, lord_a, lord_b):
            continue
        for first_lord, second_lord in principal_orders:
            separation_event = _translation_separation_event(
                chrt, trans_pid, first_lord, aspect_list, orb,
            )
            if separation_event is None:
                continue
            reception = [
                level for level in _reception_levels_of(
                    chrt, trans_pid, first_lord,
                )
                if level in reception_target
            ]
            if require_reception and not reception:
                continue
            target_event = _perfecting_event(
                chrt, trans_pid, second_lord, aspect_list, orb,
            )
            if target_event is None:
                continue
            target_applicators = _aspect_applicator_pids(
                chrt, trans_pid, second_lord, target_event['angle'],
            )
            if trans_pid not in target_applicators:
                continue
            direct_event = _earliest_direct_principal_event(
                chrt, lord_a, lord_b, _TRANSLATION_PRINCIPAL_ASPECTS,
                orb,
            )
            if (direct_event is not None
                    and float(direct_event['days'])
                    <= float(target_event['days']) + 1.0e-9):
                continue
            intervening = _earliest_other_contact(
                chrt, trans_pid, second_lord, aspect_list,
                target_event['days'],
            )
            if (intervening is not None and
                    intervening['event']['days'] <=
                    target_event['days'] + 1.0e-9):
                continue
            return {
                'from_house': int(fh) if fh is not None else None,
                'to_house': int(th) if th is not None else None,
                'principal_labels': labels,
                'lord_a': lord_a, 'lord_b': lord_b,
                'translator': trans_pid,
                'first_lord': first_lord,
                'second_lord': second_lord,
                'separating_angle': separation_event['angle'],
                'separation_event': separation_event,
                'reception_levels': tuple(reception),
                'target_event': target_event,
                'direct_principal_event': direct_event,
                'intervening': intervening,
                'direction': selected_direction,
                'house_frame': str(house_frame),
            }
    return None


def translation_of_light(chrt, context=None,
                          from_house=None, to_house=None,
                          orb=6.0, aspects=(0, 60, 90, 120, 180),
                          reception_levels=('domicile', 'triplicity', 'term'),
                          require_reception=True, translator=None,
                          direction='either', house_frame='profile', **_):
    """Third planet separates from one significator and applies to the other.

    Horary perfection path #2. Falls back to `context["querent_house"]`
    and `context["quesited_house"]` when `from_house` / `to_house` are
    None, so the predicate can be used either with fixed houses or in a
    context-driven rule. Any faster classical planet (Moon + Mercury +
    Venus + Mars + Jupiter + Saturn + Sun, minus the two significators)
    is a candidate translator; the first that separates from one and
    applies to the other wins. Set ``translator='moon'`` where a chapter
    explicitly names the Moon as carrier. Set ``direction='from_to'`` when
    the chapter says that light is carried from ``from_house`` to
    ``to_house``; the default ``either`` is reserved for clauses that merely
    say translation occurs between the two principals. Lilly's carrier
    sequence is enforced: the carrier's prior exact separation is resolved
    chronologically; the first significator receives the carrier where the
    rule requests reception; and the carrier reaches the second significator
    before another carrier contact or an earlier direct perfection between
    the principals. Lilly's own Mars–Mercury–Saturn example does not require
    the principals themselves to be separating.
    """
    return _translation_witness(
        chrt, context=context, from_house=from_house, to_house=to_house,
        orb=orb, aspects=aspects, reception_levels=reception_levels,
        require_reception=require_reception, translator=translator,
        direction=direction, house_frame=house_frame,
    ) is not None


def _collection_witness(chrt, context=None, houses=None, orb=6.0,
                        aspects=(0, 60, 90, 120, 180),
                        reception_levels=('domicile', 'exaltation',
                                          'triplicity', 'term', 'face'),
                        require_reception=True, principal_pids=None,
                        principal_labels=None, house_frame='profile'):
    """Return Lilly's complete collection witness, or ``None``."""
    if principal_pids is not None:
        try:
            pids = tuple(principal_pids)
        except TypeError:
            return None
        if len(pids) != 2:
            return None
        lord_a, lord_b = pids
        if (lord_a not in _PLANET_IDS.values()
                or lord_b not in _PLANET_IDS.values()):
            return None
        house_list = list(houses) if houses else [None, None]
    elif houses:
        house_list = list(houses)
    else:
        ctx = context or {}
        house_list = [ctx.get('querent_house'), ctx.get('quesited_house')]
    if len(house_list) < 2:
        return None
    if principal_pids is None:
        if None in house_list[:2]:
            return None
        lord_a = _lord_of_house(chrt, house_list[0], house_frame)
        lord_b = _lord_of_house(chrt, house_list[1], house_frame)
    if (lord_a is None or lord_b is None or lord_a == lord_b
            or _planet(chrt, lord_a) is None
            or _planet(chrt, lord_b) is None):
        return None
    if principal_labels is None:
        labels = (
            f'L{int(house_list[0])}' if house_list[0] is not None
            else planet_name_from_id(lord_a),
            f'L{int(house_list[1])}' if house_list[1] is not None
            else planet_name_from_id(lord_b),
        )
    else:
        try:
            labels = tuple(str(value) for value in principal_labels)
        except TypeError:
            return None
        if len(labels) != 2:
            return None
    aspect_list = tuple(aspects)
    # Collection exists because the principals cannot perfect directly.  A
    # current direct aspect therefore disqualifies this third-party path.
    if _body_aspect_matches(chrt, lord_a, lord_b, aspect_list, orb):
        return None
    a_pl = _planet(chrt, lord_a)
    b_pl = _planet(chrt, lord_b)
    if a_pl is None or b_pl is None:
        return None
    sa = abs(_speed(a_pl))
    sb = abs(_speed(b_pl))
    reception_target = {
        str(level).lower() for level in tuple(reception_levels)
    }
    for col_name in _CLASSICAL_PLANETS:
        col_pid = _pid(col_name)
        if col_pid in (lord_a, lord_b):
            continue
        col = _planet(chrt, col_pid)
        if col is None:
            continue
        sc = abs(_speed(col))
        if sc >= sa or sc >= sb:
            continue
        event_a = _perfecting_event(
            chrt, lord_a, col_pid, aspect_list, orb,
        )
        event_b = _perfecting_event(
            chrt, lord_b, col_pid, aspect_list, orb,
        )
        if event_a is None or event_b is None:
            continue
        if (lord_a not in _aspect_applicator_pids(
                chrt, lord_a, col_pid, event_a['angle'])
                or lord_b not in _aspect_applicator_pids(
                    chrt, lord_b, col_pid, event_b['angle'])):
            continue
        receives_a = [
            level for level in _reception_levels_of(
                chrt, col_pid, lord_a,
            )
            if level in reception_target
        ]
        receives_b = [
            level for level in _reception_levels_of(
                chrt, col_pid, lord_b,
            )
            if level in reception_target
        ]
        if require_reception and not (receives_a and receives_b):
            continue
        return {
            'houses': tuple(
                int(value) if value is not None else None
                for value in house_list[:2]
            ),
            'principal_labels': labels,
            'lord_a': lord_a, 'lord_b': lord_b,
            'collector': col_pid,
            'event_a': event_a, 'event_b': event_b,
            'reception_a': tuple(receives_a),
            'reception_b': tuple(receives_b),
            'house_frame': str(house_frame),
        }
    return None


def collection_of_light(chrt, context=None, houses=None,
                         orb=6.0, aspects=(0, 60, 90, 120, 180),
                         reception_levels=('domicile', 'exaltation',
                                           'triplicity', 'term', 'face'),
                         require_reception=True, house_frame='profile', **_):
    """A slower heavy planet receives both significators' application.

    Horary perfection path #3. Defaults to the querent / quesited lords;
    pass an explicit `houses=[a, b]` to override. Any classical planet
    slower than both significators and aspected by both is a candidate. Lilly
    also requires that the principals do not behold one another and that each
    significator receives the collector in one of its essential dignities.
    """
    return _collection_witness(
        chrt, context=context, houses=houses, orb=orb, aspects=aspects,
        reception_levels=reception_levels,
        require_reception=require_reception, house_frame=house_frame,
    ) is not None


