def _lilly_treasure_translation_event(
        chrt, context=None, orb=6.0,
        aspects=(0, 60, 90, 120, 180),
        reception_levels=('domicile', 'triplicity', 'term'),
        require_reception=True, translator=None, direction='either',
        aspect_frame='degree', orb_policy='lilly_moiety',
        dignity_frame='lilly'):
    principals = _lilly_treasure_principals(chrt, context=context)
    if principals is None or principals['role_collision']:
        return None
    with semantic_scope({
            'aspect_frame': aspect_frame,
            'orb_policy': orb_policy,
            'dignity_frame': dignity_frame,
    }):
        witness = _translation_witness(
            chrt, orb=orb, aspects=aspects,
            reception_levels=reception_levels,
            require_reception=require_reception, translator=translator,
            direction=direction,
            principal_pids=(
                principals['significator_pid'], principals['lord_1_pid'],
            ),
            principal_labels=('treasure significator', 'L1'),
        )
    if witness is None:
        return None
    result = dict(principals)
    result['translation'] = witness
    return result


