def _lilly_theft_voluntary_return_event(chrt, *, house_frame='profile'):
    lord_1 = _lord_of_house(chrt, 1)
    lord_7 = _lord_of_house(chrt, 7)
    lord_8 = _lord_of_house(chrt, 8)
    routes = []
    if lord_1 is None or lord_7 is None:
        return None
    if _lilly_body_house(chrt, lord_1, house_frame) == 7:
        routes.append({'route': 'l1_in_h7', 'pids': (lord_1,)})
    if _lilly_current_relation_event(chrt, lord_1, lord_8, (0,)) is not None:
        routes.append({'route': 'l1_conjunct_l8',
                       'pids': (lord_1, lord_8)})
    if _lilly_body_house(chrt, lord_7, house_frame) == 1:
        routes.append({'route': 'l7_in_h1', 'pids': (lord_7,)})
    for pid in _PLANET_IDS.values():
        body = _planet(chrt, pid)
        if (pid == astrology.SE_MOON or body is None
                or _speed(body) >= 0.0):
            continue
        if _lilly_current_relation_event(
                chrt, astrology.SE_MOON, pid, (0,)) is not None:
            routes.append({'route': 'moon_joined_retrograde_planet',
                           'pids': (astrology.SE_MOON, pid)})
    return {'outcome': 'voluntary_return', 'routes': tuple(routes)} if routes else None


def lilly_theft_voluntary_return(chrt, house_frame='profile', **_):
    return _lilly_theft_voluntary_return_event(
        chrt, house_frame=house_frame,
    ) is not None


def _lilly_point_relation_exists(chrt, pid, longitude):
    if pid is None or longitude is None:
        return False
    return bool(_longitude_aspect_matches(
        chrt, (pid,), longitude, 'FORTUNE', _PTOLEMAIC_ASPECTS,
        None, 'lilly_moiety', 'degree', endpoint_kind='zodiacal_point',
    ))


def _lilly_theft_restitution_status_event(
        chrt, *, context=None,
        reception_context_key='theft_restitution_reception_reading',
        house_frame='profile', dignity_frame='profile'):
    lord_1 = _lord_of_house(chrt, 1)
    lord_2 = _lord_of_house(chrt, 2)
    lord_7 = _lord_of_house(chrt, 7)
    lord_8 = _lord_of_house(chrt, 8)
    restored = []
    denied = []
    if None in (lord_1, lord_2, lord_7, lord_8):
        return {'outcome': 'unknown', 'restored': (), 'denied': ()}
    conjunctions = []
    for role, principal in (('lord_1', lord_1), ('lord_2', lord_2)):
        event = _lilly_current_relation_event(
            chrt, principal, lord_8, (0,),
        )
        if event is not None:
            conjunctions.append({
                'route': f'{role}_conjunct_l8',
                'pids': (principal, lord_8), 'event': event,
            })
    if len(conjunctions) == 2:
        restored.append({
            'route': 'l1_and_l2_conjunct_l8',
            'pids': tuple(dict.fromkeys((lord_1, lord_2, lord_8))),
            'relations': tuple(conjunctions),
        })
    reception_reading = _lilly_normalized_choice(
        (context or {}).get(
            reception_context_key, 'both_mutual_with_l8',
        ),
        'both_mutual_with_l8',
    )
    if lilly_goods_restored_strong_reception(
            chrt, houses=(1, 2, 8),
            reception_relation=reception_reading,
            levels=('domicile', 'exaltation'),
            dignity_frame=dignity_frame):
        restored.append({
            'route': 'strong_reception_selected_reading',
            'reading': reception_reading,
            'pids': (lord_1, lord_2, lord_8),
        })
    if lord_2 != astrology.SE_SUN:
        body = _planet(chrt, lord_2)
        sun = _planet(chrt, astrology.SE_SUN)
        if body is not None and sun is not None:
            arc = _ang_diff(_lon(body), _lon(sun))
            phase = _aspect_direction(
                chrt, lord_2, astrology.SE_SUN, 0, None,
                'lilly_moiety',
            )
            if (_sign(_lon(body)) == _sign(_lon(sun))
                    and 17.0 / 60.0 < arc <= 17.0 and phase == 'separating'):
                restored.append({
                    'route': 'l2_departing_combustion',
                    'pids': (lord_2, astrology.SE_SUN), 'arc': arc,
                    'solar_grade': ('combust' if arc <= 8.5
                                    else 'under_beams'),
                })
    for luminary in (astrology.SE_SUN, astrology.SE_MOON):
        house = _lilly_body_house(chrt, luminary, house_frame)
        if house in (1, 10):
            restored.append({'route': 'luminary_in_h1_or_h10',
                             'pids': (luminary,), 'house': house})
    lights = _lilly_current_relation_event(
        chrt, astrology.SE_SUN, astrology.SE_MOON,
        _PTOLEMAIC_ASPECTS,
    )
    if lights is not None:
        restored.append({'route': 'lights_behold_each_other',
                         'pids': (astrology.SE_SUN, astrology.SE_MOON),
                         'event': lights})

    if lord_of_house_combust(
            chrt, house=2, orb=8.5, cazimi_orb=17.0 / 60.0):
        denied.append({'route': 'l2_combust',
                       'pids': (lord_2, astrology.SE_SUN)})
    if _lilly_current_relation_event(chrt, lord_7, lord_8, (0,)) is not None:
        denied.append({'route': 'l7_conjunct_l8',
                       'pids': (lord_7, lord_8)})
    l2_to_l1 = _lilly_current_relation_event(
        chrt, lord_2, lord_1, _PTOLEMAIC_ASPECTS,
    )
    l2_to_asc = _point_aspect_matches(
        chrt, (lord_2,), point='ASC', aspects=_PTOLEMAIC_ASPECTS,
        orb=None, orb_policy='lilly_moiety',
        point_orb_policy='lilly_moiety', point_frame='degree',
    )
    if l2_to_l1 is None and not l2_to_asc:
        denied.append({'route': 'l2_beholds_neither_h1_nor_l1',
                       'pids': (lord_2, lord_1)})
    fortune = _part_of_fortune_lon(chrt)
    if (lights is None
            and not _lilly_point_relation_exists(
                chrt, astrology.SE_SUN, fortune)
            and not _lilly_point_relation_exists(
                chrt, astrology.SE_MOON, fortune)):
        denied.append({'route': 'lights_behold_neither_each_other_nor_fortune',
                       'pids': (astrology.SE_SUN, astrology.SE_MOON)})
    if both_luminaries_below_horizon(chrt):
        denied.append({'route': 'both_luminaries_under_earth',
                       'pids': (astrology.SE_SUN, astrology.SE_MOON)})
    if restored and denied:
        outcome = 'conflict'
    elif restored:
        outcome = 'restored'
    elif denied:
        outcome = 'not_restored'
    else:
        outcome = 'unknown'
    return {
        'outcome': outcome, 'restored': tuple(restored),
        'denied': tuple(denied),
        'reception_reading': reception_reading,
    }


