def _ancient_selected(default, allowed, context, context_key):
    return _lilly_context_choice(
        default, allowed, context=context, context_key=context_key,
    )


def _ancient_subject(chrt, pid, role, **extra):
    body = _planet(chrt, pid)
    return {
        'pid': int(pid), 'name': planet_name_from_id(pid),
        'longitude': _lon(body) if body is not None else None,
        'role': role, **extra,
    }


def _ancient_clause(label, evidence, subjects=(), **extra):
    return {
        'label': str(label), 'evidence': str(evidence),
        'subjects': tuple(dict(row) for row in tuple(subjects)), **extra,
    }


def _ancient_compound_event(name, clauses, **extra):
    rows = tuple(clauses)
    if not rows or any(row is None for row in rows):
        return None
    return {
        'name': str(name), 'clauses': rows,
        'geometry': 'ancient_source_condition_ledger', **extra,
    }


def _ancient_aspect_doctrine():
    frame = str(_semantic_value(
        'aspect_frame', 'profile', 'sign',
    ) or 'sign').lower().replace('-', '_')
    orb_policy = str(_semantic_value(
        'orb_policy', 'profile', 'unresolved',
    ) or 'unresolved').lower().replace('-', '_')
    return frame, orb_policy


def _ancient_relation_rows(chrt, a_pid, b_pid, aspects, *, role):
    """Measured testimony; unresolved degree allowances fail closed."""
    frame, orb_policy = _ancient_aspect_doctrine()
    angles = tuple(float(value) for value in tuple(aspects))
    if frame in ('sign', 'whole_sign', 'sign_configuration'):
        rows = _body_aspect_matches(
            chrt, a_pid, b_pid, angles, orb=None,
            orb_policy='unresolved', aspect_frame='sign',
        )
        doctrine = 'none'
    elif frame in ('degree', 'zodiacal_degree'):
        if any(_body_orb_limit(
                chrt, a_pid, b_pid, angle, None, orb_policy,
        )[0] is None for angle in angles):
            return None
        rows = _body_aspect_matches(
            chrt, a_pid, b_pid, angles, orb=None,
            orb_policy=orb_policy, aspect_frame='degree',
        )
        doctrine = orb_policy
    else:
        return None
    decorated = []
    for raw in rows:
        row = dict(raw)
        row.update({
            'a_name': planet_name_from_id(a_pid),
            'b_name': planet_name_from_id(b_pid), 'role': role,
        })
        decorated.append(row)
    return {'rows': tuple(decorated), 'frame': frame,
            'orb_policy': doctrine}


def _ancient_relation_clause(chrt, a_pid, b_pid, aspects, label, role):
    relation = _ancient_relation_rows(
        chrt, a_pid, b_pid, aspects, role=role,
    )
    if relation is None or not relation['rows']:
        return None
    row = relation['rows'][0]
    measurement = (
        f"sign testimony {float(row['angle']):g}°"
        if row['geometry'] == 'sign_configuration' else
        f"{float(row['angle']):g}° arc "
        f"{float(row['arc']):.6f}°/{float(row['max_orb']):.6f}°"
    )
    return _ancient_clause(
        label,
        f"{planet_name_from_id(a_pid).title()}↔"
        f"{planet_name_from_id(b_pid).title()} {measurement} · "
        f"[aspect-frame:{relation['frame']}] · "
        f"[orb-policy:{relation['orb_policy']}]",
        tuple(_ancient_subject(chrt, pid, role)
              for pid in (a_pid, b_pid)),
        relation=relation,
    )


def _ancient_no_class_testimony_clause(
        chrt, target_pid, witness_pids, aspects, label, role):
    checked = []
    for witness_pid in tuple(witness_pids):
        relation = _ancient_relation_rows(
            chrt, witness_pid, target_pid, aspects, role=role,
        )
        if relation is None or relation['rows']:
            return None
        checked.append(relation)
    names = '/'.join(planet_name_from_id(pid).title()
                     for pid in tuple(witness_pids))
    frame = checked[0]['frame'] if checked else None
    doctrine = checked[0]['orb_policy'] if checked else None
    return _ancient_clause(
        label,
        f"no {names} testimony to {planet_name_from_id(target_pid).title()} "
        f"· [angles:{'/'.join(f'{float(a):g}' for a in aspects)}] · "
        f"[aspect-frame:{frame}] · [orb-policy:{doctrine}]",
        (_ancient_subject(chrt, target_pid, role),),
        checked_relations=tuple(checked),
    )


def _ancient_unharmed_clause(
        chrt, pid, policy='malefic_testimony',
        policy_context_key=None, context=None):
    selected = _ancient_selected(
        policy, _ANCIENT_HARM_POLICIES, context, policy_context_key,
    )
    if selected is None or selected['value'] == 'source_phrase_only':
        return None
    clause = _ancient_no_class_testimony_clause(
        chrt, pid, (astrology.SE_MARS, astrology.SE_SATURN),
        (0, 60, 90, 120, 180), 'unharmed', 'harm_subject',
    )
    if clause is not None:
        clause['evidence'] += (
            f" · [harm-policy:{selected['value'].replace('_', '-')}]"
        )
        clause['policy'] = selected
    return clause


def _ancient_place_clause(
        chrt, pid, policy='nechepso_eight',
        policy_context_key=None, context=None, role='place_subject'):
    selected = _ancient_selected(
        policy, _ANCIENT_PLACE_POLICIES, context, policy_context_key,
    )
    if selected is None:
        return None
    places = _ANCIENT_PLACE_POLICIES[selected['value']]
    if places is None:
        return None
    body = _planet(chrt, pid)
    longitude = _lon(body) if body is not None else None
    frame = str(_semantic_value(
        'house_frame', 'profile', 'whole_sign',
    ) or 'whole_sign').lower().replace('-', '_')
    house = _house_of_frame(chrt, longitude, frame)
    if house not in places:
        return None
    return _ancient_clause(
        'well placed',
        f"{planet_name_from_id(pid).title()} H{int(house)} · "
        f"[place-list:{selected['value'].replace('_', '-')}] · "
        f"[house-frame:{frame.replace('_', '-')}]",
        (_ancient_subject(chrt, pid, role, house=int(house)),),
        policy=selected, house=int(house), house_frame=frame,
    )


def _ancient_benefic_testimony_clause(
        chrt, pid, *, require_both=False, label='benefic testimony'):
    clauses = []
    for benefic in (astrology.SE_JUPITER, astrology.SE_VENUS):
        relation = _ancient_relation_clause(
            chrt, benefic, pid, (0, 60, 90, 120, 180),
            label, 'benefic_witness',
        )
        if relation is not None:
            clauses.append(relation)
        elif require_both:
            return None
    if not clauses:
        return None
    return _ancient_clause(
        label,
        f"[benefic-requirement:{'both' if require_both else 'at-least-one'}]",
        tuple(subject for row in clauses for subject in row['subjects']),
        witnesses=tuple(clauses), require_both=bool(require_both),
    )


def _planet_number_event(
        chrt, pid, policy='direct_motion',
        policy_context_key=None, context=None):
    selected = _ancient_selected(
        policy, _HEPHAISTION_ADDITIVE_POLICIES,
        context, policy_context_key,
    )
    if selected is None or selected['value'] == 'source_phrase_only':
        return None
    try:
        anchor = float(chrt.time.jd)
    except (AttributeError, TypeError, ValueError):
        return None
    ephemeris = _corpus_station_context(chrt)
    speed = _station_speed_at(ephemeris, pid, anchor) \
        if ephemeris is not None else None
    if speed is None:
        return None
    acceleration = None
    if selected['value'] == 'direct_motion':
        matched = float(speed) > 0.0
        definition = 'positive_longitude_speed'
    else:
        half_window = 1.0 / 48.0
        before = _station_speed_at(ephemeris, pid, anchor - half_window)
        after = _station_speed_at(ephemeris, pid, anchor + half_window)
        if before is None or after is None:
            return None
        acceleration = (float(after) - float(before)) / (2.0 * half_window)
        matched = acceleration > 0.0
        definition = 'positive_longitude_acceleration'
    if not matched:
        return None
    return {
        'pid': int(pid), 'name': planet_name_from_id(pid),
        'longitude_speed': float(speed),
        'longitude_acceleration': acceleration,
        'policy': selected, 'definition': definition,
        'coordinate_frame': 'geocentric_tropical',
    }


