def _ancient_number_clause(
        chrt, pid, policy, policy_context_key, context, *, label, role):
    event = _planet_number_event(
        chrt, pid, policy=policy,
        policy_context_key=policy_context_key, context=context,
    )
    if event is None:
        return None
    evidence = (
        f"{planet_name_from_id(pid).title()} longitude speed "
        f"{event['longitude_speed']:.9f}°/day"
    )
    if event['longitude_acceleration'] is not None:
        evidence += (
            f"; acceleration {event['longitude_acceleration']:.9f}"
            "°/day²"
        )
    evidence += (
        f" · [additive-policy:{event['policy']['value'].replace('_', '-')}]"
        " · [coordinate-frame:geocentric-tropical]"
    )
    return _ancient_clause(
        label, evidence, (_ancient_subject(chrt, pid, role),), event=event,
    )


