def _hephaistion_foundation_eclipse_event(
        chrt, reading='source_phrase_only', reading_context_key=None,
        context=None, **_):
    """Dykes fn.179 reconstruction of Heph. III.7's damaged syntax.

    The opt-in reading has two physical-event branches: a solar eclipse with
    the Moon in the fourth place, or an eclipsed Moon in the fourth place.
    Either branch additionally requires measured malefic harm.  The Swiss
    Ephemeris event state admits the eclipse itself; no opposition orb or
    elapsed-time window stands in for an eclipse.
    """
    selected = _ancient_selected(
        reading, _HEPHAISTION_FOUNDATION_ECLIPSE_READINGS,
        context, reading_context_key,
    )
    if (selected is None
            or selected['value'] != 'dykes_2013_two_eclipse_branches'):
        return None
    try:
        anchor = float(chrt.time.jd)
    except (AttributeError, TypeError, ValueError):
        return None
    try:
        import eclipses as eclipse_engine
        eclipse_state = eclipse_engine.eclipse_state_at_jdut(anchor)
    except Exception:
        eclipse_state = None
    if eclipse_state is None:
        return None

    moon = _planet(chrt, astrology.SE_MOON)
    moon_lon = _lon(moon) if moon is not None else None
    house_frame = str(_semantic_value(
        'house_frame', 'profile', 'whole_sign',
    ) or 'whole_sign').lower().replace('-', '_')
    moon_house = _house_of_frame(chrt, moon_lon, house_frame)
    if moon_lon is None or moon_house != 4:
        return None

    relations = []
    for malefic in (astrology.SE_MARS, astrology.SE_SATURN):
        clause = _ancient_relation_clause(
            chrt, malefic, astrology.SE_MOON,
            (0, 60, 90, 120, 180),
            f"{planet_name_from_id(malefic).title()} harms Moon",
            'foundation_eclipse_harm',
        )
        if clause is not None:
            relations.append(clause)
    if not relations:
        return None

    event_kind = str(eclipse_state.get('kind') or '')
    if event_kind not in ('solar_eclipse', 'lunar_eclipse'):
        return None
    branch = (
        'solar_eclipse_moon_fourth'
        if event_kind == 'solar_eclipse'
        else 'eclipsed_moon_fourth'
    )
    magnitude = eclipse_state.get('magnitude')
    magnitude_text = (
        f"; magnitude {float(magnitude):.6f}"
        if isinstance(magnitude, (int, float)) else ''
    )
    eclipse_clause = _ancient_clause(
        'physical eclipse active at the chart instant',
        f"{event_kind.replace('_', ' ')} "
        f"{str(eclipse_state.get('classification') or 'unknown')}; "
        f"JD UT {float(eclipse_state['jd_ut']):.9f}; retflag "
        f"{int(eclipse_state['retflag'])}; syzygy residual "
        f"{float(eclipse_state['phase_residual_deg']):.9f}°; Moon latitude "
        f"{float(eclipse_state['moon_latitude_deg']):+.9f}°"
        f"{magnitude_text} · [event-source:swiss-ephemeris-instant-state] "
        f"· [eclipse-reading:{selected['value'].replace('_', '-')}] "
        "· [admission:no-aspect-or-time-window]",
        (_ancient_subject(
            chrt, astrology.SE_MOON, 'foundation_eclipse_moon',
        ),),
        event=dict(eclipse_state), policy=selected, branch=branch,
    )
    place_clause = _ancient_clause(
        'Moon in the fourth place',
        f"Moon {_SIGN_SHORT[_sign(moon_lon)]} "
        f"{_deg_in_sign(moon_lon):.6f}°; H4 · "
        f"[{_house_frame_token(chrt, house_frame)}]",
        (_ancient_subject(
            chrt, astrology.SE_MOON, 'foundation_eclipse_moon',
            house=4,
        ),),
        house=4, house_frame=house_frame,
    )
    harm_clause = _ancient_clause(
        'Moon harmed by at least one malefic',
        ' OR '.join(clause['evidence'] for clause in relations)
        + ' · [malefic-requirement:at-least-one]',
        tuple(
            subject for clause in relations
            for subject in clause.get('subjects', ())
        ),
        witnesses=tuple(relations),
    )
    return _ancient_compound_event(
        'hephaistion_foundation_eclipse_warning',
        (eclipse_clause, place_clause, harm_clause),
        source='Heph. III.7 §6–7; Dykes 2013 fn.179',
        branch=branch, policy=selected, eclipse_state=dict(eclipse_state),
    )


