def _hephaistion_conception_moon_event(
        chrt, harm_policy='malefic_testimony',
        harm_policy_context_key=None,
        harmony_policy='whole_sign_trine',
        harmony_policy_context_key=None, context=None, **_):
    harm = _ancient_unharmed_clause(
        chrt, astrology.SE_MOON, policy=harm_policy,
        policy_context_key=harm_policy_context_key, context=context,
    )
    selected = _ancient_selected(
        harmony_policy, _HEPHAISTION_HARMONY_POLICIES,
        context, harmony_policy_context_key,
    )
    harmony = None
    moon = _planet(chrt, astrology.SE_MOON)
    moon_lon = _lon(moon) if moon is not None else None
    asc = _asc(chrt)
    if (selected is not None
            and selected['value'] != 'source_phrase_only'
            and moon_lon is not None and asc is not None):
        if selected['value'] == 'whole_sign_trine':
            sign_distance = (_sign(moon_lon) - _sign(asc)) % 12
            if sign_distance in (4, 8):
                harmony = _ancient_clause(
                    'Moon harmonious to the Hour-marker',
                    f"Moon sign {_sign(moon_lon)} and ASC sign {_sign(asc)} "
                    "form a whole-sign trine · "
                    "[harmony-policy:whole-sign-trine]",
                    (_ancient_subject(
                        chrt, astrology.SE_MOON, 'conception_moon',
                    ),), policy=selected,
                )
        else:
            harmony = _ancient_point_relation_clause(
                chrt, astrology.SE_MOON, 'ASC', (120,),
                'Moon harmonious to the Hour-marker', 'conception_moon',
            )
            if harmony is not None:
                harmony['policy'] = selected
                harmony['evidence'] += ' · [harmony-policy:profile-trine]'
    return _ancient_compound_event(
        'hephaistion_conception_moon', (harm, harmony),
        source='Heph. III.10 §3',
    )


