def _hephaistion_freed_captive_inquiry_event(
        chrt, harm_policy='malefic_testimony',
        harm_policy_context_key=None, context=None, **_):
    """Heph. III.4 §17 as one complete, non-voting inquiry figure."""
    fortune = _part_of_fortune_lon(chrt)
    if fortune is None:
        return None
    frame = str(_semantic_value(
        'house_frame', 'profile', 'whole_sign',
    ) or 'whole_sign').lower().replace('-', '_')
    fortune_house = _house_of_frame(chrt, fortune, frame)
    fortune_lord = _sign_ruler_at(chrt, _sign(fortune))
    if fortune_house != 3 or fortune_lord is None:
        return None
    lot = _ancient_clause(
        'Lot in the place pertaining to friends',
        f"Fortune {float(fortune):.6f}° in H3 · "
        f"[house-frame:{frame.replace('_', '-')}]",
        ({
            'pid': None, 'name': 'fortune', 'longitude': float(fortune),
            'role': 'inquiry_lot', 'house': 3,
        },), house=3, house_frame=frame,
    )

    fortune_body = _planet(chrt, fortune_lord)
    fortune_lord_lon = _lon(fortune_body) if fortune_body is not None else None
    fortune_lord_house = _house_of_frame(chrt, fortune_lord_lon, frame)
    if fortune_lord_house != 12:
        return None
    bad_spirit = _ancient_clause(
        "Fortune's lord in Bad Spirit",
        f"{planet_name_from_id(fortune_lord).title()} H12 · "
        f"[house-frame:{frame.replace('_', '-')}]",
        (_ancient_subject(
            chrt, fortune_lord, 'fortune_lord', house=12,
        ),), house=12, house_frame=frame,
    )

    hour_lord = _lord_of_house(chrt, 1)
    witness_relations = []
    for witness_pid in dict.fromkeys((
            astrology.SE_JUPITER, astrology.SE_VENUS, hour_lord)):
        if witness_pid is None or int(witness_pid) == int(fortune_lord):
            continue
        relation = _ancient_relation_clause(
            chrt, fortune_lord, int(witness_pid), (0,),
            "Fortune's lord with a benefic or Hour-lord",
            'freed_captive_witness',
        )
        if relation is not None:
            witness_relations.append(relation)
    if not witness_relations:
        return None
    witness = _ancient_clause(
        "Fortune's lord with a benefic or Hour-lord",
        '[requirement:at-least-one] · [relation:co-presence/contact]',
        tuple(
            subject for row in witness_relations for subject in row['subjects']
        ), relations=tuple(witness_relations),
    )

    bad_spirit_lord = _lord_of_house(chrt, 12)
    if bad_spirit_lord is None:
        return None
    on_hour_marker = (
        _ancient_point_relation_clause(
            chrt, bad_spirit_lord, 'ASC', (0,),
            'Bad-Spirit ruler on the Hour-marker',
            'bad_spirit_lord',
        )
    )
    moon_unharmed = _ancient_unharmed_clause(
        chrt, astrology.SE_MOON, policy=harm_policy,
        policy_context_key=harm_policy_context_key, context=context,
    )
    return _ancient_compound_event(
        'hephaistion_freed_captive_inquiry',
        (lot, bad_spirit, witness, on_hour_marker, moon_unharmed),
        source='Heph. III.4 §17', fortune_lord_pid=int(fortune_lord),
        bad_spirit_lord_pid=int(bad_spirit_lord),
    )


def hephaistion_freed_captive_inquiry(
        chrt, harm_policy='malefic_testimony',
        harm_policy_context_key=None, context=None, **_):
    return _hephaistion_freed_captive_inquiry_event(
        chrt, harm_policy=harm_policy,
        harm_policy_context_key=harm_policy_context_key,
        context=context,
    ) is not None


def _hephaistion_court_luminary_factors(
        chrt, pid, place_policy, place_policy_context_key, context):
    """Return four complete yes/no factors; indeterminate legs fail closed."""
    selected_place = _ancient_selected(
        place_policy, _ANCIENT_PLACE_POLICIES,
        context, place_policy_context_key,
    )
    if selected_place is None:
        return None
    good_places = _ANCIENT_PLACE_POLICIES[selected_place['value']]
    if good_places is None:
        return None
    body = _planet(chrt, pid)
    longitude = _lon(body) if body is not None else None
    if longitude is None:
        return None
    name = planet_name_from_id(pid).title()
    frame = str(_semantic_value(
        'house_frame', 'profile', 'whole_sign',
    ) or 'whole_sign').lower().replace('-', '_')
    house = _house_of_frame(chrt, longitude, frame)
    bound_lord = _term_ruler_at(chrt, longitude)
    above = _body_above_horizon(chrt, pid)
    if house is None or bound_lord is None or above is None:
        return None

    testimony_relations = []
    for benefic in (astrology.SE_JUPITER, astrology.SE_VENUS):
        relation = _ancient_relation_rows(
            chrt, benefic, pid, (0, 60, 90, 120, 180),
            role='court_benefic_testimony',
        )
        if relation is None:
            return None
        if relation['rows']:
            testimony_relations.append(relation)

    factors = {
        'good_place': int(house) in good_places,
        'benefic_bound': int(bound_lord) in (
            astrology.SE_JUPITER, astrology.SE_VENUS,
        ),
        'benefic_testimony': bool(testimony_relations),
        'above_earth': bool(above),
    }
    clauses = (
        _ancient_clause(
            f'{name} good-place factor',
            f"H{int(house)} · [place-list:"
            f"{selected_place['value'].replace('_', '-')}] · "
            f"[house-frame:{frame.replace('_', '-')}] · "
            f"[satisfied:{'yes' if factors['good_place'] else 'no'}]",
            (_ancient_subject(chrt, pid, 'court_party_light', house=int(house)),),
        ),
        _ancient_clause(
            f'{name} benefic-bound factor',
            f"bound ruler {planet_name_from_id(bound_lord).title()} · "
            f"[dignity-frame:profile] · "
            f"[satisfied:{'yes' if factors['benefic_bound'] else 'no'}]",
            (
                _ancient_subject(chrt, pid, 'court_party_light'),
                _ancient_subject(chrt, bound_lord, 'court_bound_lord'),
            ),
        ),
        _ancient_clause(
            f'{name} benefic-testimony factor',
            f"witnesses "
            f"{('/'.join(planet_name_from_id(int(row['rows'][0]['a_pid'])).title() for row in testimony_relations) or 'none')} · "
            f"[aspect-frame:{_ancient_aspect_doctrine()[0]}] · "
            f"[satisfied:{'yes' if factors['benefic_testimony'] else 'no'}]",
            (_ancient_subject(chrt, pid, 'court_party_light'),),
            relations=tuple(testimony_relations),
        ),
        _ancient_clause(
            f'{name} above-earth factor',
            f"astronomical hemisphere "
            f"{'above' if factors['above_earth'] else 'below'} · "
            f"[satisfied:{'yes' if factors['above_earth'] else 'no'}]",
            (_ancient_subject(chrt, pid, 'court_party_light'),),
        ),
    )
    return {
        'pid': int(pid), 'factors': factors,
        'score': sum(int(value) for value in factors.values()),
        'clauses': clauses, 'place_policy': selected_place,
    }


def _hephaistion_court_strength_event(
        chrt, aggregation='strict_factor_dominance',
        aggregation_context_key=None, tie_policy='report_tie',
        tie_policy_context_key=None, place_policy='nechepso_eight',
        place_policy_context_key=None, context=None, **_):
    selected_aggregation = _ancient_selected(
        aggregation, _HEPHAISTION_COURT_STRENGTH_AGGREGATIONS,
        context, aggregation_context_key,
    )
    selected_tie = _ancient_selected(
        tie_policy, _HEPHAISTION_COURT_STRENGTH_TIE_POLICIES,
        context, tie_policy_context_key,
    )
    if (selected_aggregation is None or selected_tie is None
            or selected_aggregation['value'] == 'source_phrase_only'
            or selected_tie['value'] == 'source_phrase_only'):
        return None
    moon = _hephaistion_court_luminary_factors(
        chrt, astrology.SE_MOON, place_policy,
        place_policy_context_key, context,
    )
    sun = _hephaistion_court_luminary_factors(
        chrt, astrology.SE_SUN, place_policy,
        place_policy_context_key, context,
    )
    elongation = _moon_elong(chrt)
    if moon is None or sun is None or elongation is None:
        return None

    factor_names = tuple(moon['factors'])
    if selected_aggregation['value'] == 'equal_factor_count':
        if moon['score'] > sun['score']:
            outcome = 'moon_prevails'
        elif sun['score'] > moon['score']:
            outcome = 'sun_prevails'
        else:
            outcome = 'tie'
    else:
        moon_dominates = (
            all(moon['factors'][name] >= sun['factors'][name]
                for name in factor_names)
            and any(moon['factors'][name] > sun['factors'][name]
                    for name in factor_names)
        )
        sun_dominates = (
            all(sun['factors'][name] >= moon['factors'][name]
                for name in factor_names)
            and any(sun['factors'][name] > moon['factors'][name]
                    for name in factor_names)
        )
        if moon_dominates:
            outcome = 'moon_prevails'
        elif sun_dominates:
            outcome = 'sun_prevails'
        elif moon['factors'] == sun['factors']:
            outcome = 'tie'
        else:
            outcome = 'no_strict_dominance'
    if outcome == 'tie' and selected_tie['value'] == 'suppress_tie':
        return None

    waxing = float(elongation) < 180.0
    party_roles = {
        'moon': 'pursuer' if waxing else 'accused',
        'sun': 'accused' if waxing else 'pursuer',
    }
    winner = (
        party_roles['moon'] if outcome == 'moon_prevails' else
        party_roles['sun'] if outcome == 'sun_prevails' else None
    )
    outcome_clause = _ancient_clause(
        'court-party comparison outcome',
        f"Moon {moon['score']}/4 ({party_roles['moon']}); "
        f"Sun {sun['score']}/4 ({party_roles['sun']}) · "
        f"[aggregation:{selected_aggregation['value'].replace('_', '-')}] · "
        f"[tie-policy:{selected_tie['value'].replace('_', '-')}] · "
        f"[outcome:{outcome.replace('_', '-')}]"
        + (f" · [prevailing-party:{winner}]" if winner else ''),
        (
            _ancient_subject(chrt, astrology.SE_MOON, party_roles['moon']),
            _ancient_subject(chrt, astrology.SE_SUN, party_roles['sun']),
        ), outcome=outcome, prevailing_party=winner,
    )
    return _ancient_compound_event(
        'hephaistion_court_party_strength',
        (*moon['clauses'], *sun['clauses'], outcome_clause),
        source='Heph. III.38 §3', moon=moon, sun=sun,
        outcome=outcome, prevailing_party=winner,
        party_roles=party_roles, aggregation=selected_aggregation,
        tie_policy=selected_tie,
    )


