def _hephaistion_court_contact_roles_event(
        chrt, aspect_set='co_presence_and_classical',
        aspect_set_context_key=None, course='moon_sign',
        course_context_key=None, tie_policy='require_unique',
        tie_policy_context_key=None, context=None, **_):
    selected_aspects = _ancient_selected(
        aspect_set, _HEPHAISTION_COURT_CONTACT_ASPECT_SETS,
        context, aspect_set_context_key,
    )
    selected_course = _ancient_selected(
        course, _HEPHAISTION_COURT_CONTACT_COURSES,
        context, course_context_key,
    )
    selected_tie = _ancient_selected(
        tie_policy, _HEPHAISTION_COURT_CONTACT_TIE_POLICIES,
        context, tie_policy_context_key,
    )
    if (selected_aspects is None or selected_course is None
            or selected_tie is None):
        return None
    aspects = _HEPHAISTION_COURT_CONTACT_ASPECT_SETS[
        selected_aspects['value']
    ]
    boundary = _HEPHAISTION_COURT_CONTACT_COURSES[
        selected_course['value']
    ]
    if (aspects is None or boundary is None
            or selected_tie['value'] == 'source_phrase_only'):
        return None
    targets = tuple(
        pid for pid in _PLANET_IDS.values()
        if pid != astrology.SE_MOON and _planet(chrt, pid) is not None
    )
    chronology = _ordered_contact_event(
        chrt, astrology.SE_MOON, targets, targets,
        aspects=aspects, boundary=boundary, orb_policy='unresolved',
        past_scope='history', tie_policy=selected_tie['value'],
    )
    if chronology is None:
        return None
    past = chronology['past_events']
    future = chronology['future_events']
    past_names = '/'.join(
        planet_name_from_id(int(row['target_pid'])).title() for row in past
    )
    future_names = '/'.join(
        planet_name_from_id(int(row['target_pid'])).title() for row in future
    )
    past_clause = _ancient_clause(
        "Moon's exact flowing-away contact assigns denouncer",
        f"{past_names}; {float(past[0]['days_ago']):.6f}d ago · "
        f"[angles:{'/'.join(f'{float(a):g}' for a in aspects)}] · "
        f"[tie-policy:{selected_tie['value'].replace('_', '-')}] · "
        '[root:exact-prior] · [present-orb-admission:none]',
        tuple(_ancient_subject(
            chrt, int(row['target_pid']), 'court_denouncer',
        ) for row in past), events=past,
    )
    matter_clause = _ancient_clause(
        'Moon signifies the matter',
        'Moon · [role:court-matter]',
        (_ancient_subject(chrt, astrology.SE_MOON, 'court_matter'),),
    )
    future_clause = _ancient_clause(
        "Moon's next exact connection assigns accused",
        f"{future_names}; in {float(future[0]['days']):.6f}d · "
        f"[angles:{'/'.join(f'{float(a):g}' for a in aspects)}] · "
        f"[course:{selected_course['value'].replace('_', '-')}] · "
        f"[boundary:{boundary.replace('_', '-')}] · "
        f"[tie-policy:{selected_tie['value'].replace('_', '-')}] · "
        '[root:exact-next] · [present-orb-admission:none]',
        tuple(_ancient_subject(
            chrt, int(row['target_pid']), 'court_accused',
        ) for row in future), events=future,
    )
    return _ancient_compound_event(
        'hephaistion_court_contact_roles',
        (past_clause, matter_clause, future_clause),
        source='Heph. III.38 §5', chronology=chronology,
        aspect_set=selected_aspects, course=selected_course,
        tie_policy=selected_tie,
    )


