def _hephaistion_human_shaped(longitude):
    if longitude is None:
        return False
    sign = _sign(longitude)
    return sign in (2, 5, 6, 10) or (sign == 8 and _deg_in_sign(longitude) < 15.0)


def _hephaistion_teaching_event(
        chrt, place_policy='nechepso_eight',
        place_policy_context_key=None,
        visibility_policy='hellenistic_15_degree',
        visibility_policy_context_key=None,
        lunar_phase_policy='exact_event_day',
        lunar_phase_policy_context_key=None, context=None, **_):
    full = _ancient_lunar_phase_clause(
        chrt, 'diameter', lunar_phase_policy,
        lunar_phase_policy_context_key, context,
        label='Moon full',
    )
    moon_place = _ancient_place_clause(
        chrt, astrology.SE_MOON, policy=place_policy,
        policy_context_key=place_policy_context_key, context=context,
        role='teaching_moon',
    )
    mercury_place = _ancient_place_clause(
        chrt, astrology.SE_MERCURY, policy=place_policy,
        policy_context_key=place_policy_context_key, context=context,
        role='teaching_mercury',
    )
    eastern = _ancient_solar_phase_clause(
        chrt, astrology.SE_MERCURY, 'eastern', visibility_policy,
        visibility_policy_context_key, context,
        label='Mercury eastern', role='teaching_mercury',
    )
    moon = _planet(chrt, astrology.SE_MOON)
    mercury = _planet(chrt, astrology.SE_MERCURY)
    moon_lon = _lon(moon) if moon is not None else None
    mercury_lon = _lon(mercury) if mercury is not None else None
    human = None
    if (_hephaistion_human_shaped(moon_lon)
            and _hephaistion_human_shaped(mercury_lon)):
        human = _ancient_clause(
            'Moon and Mercury in human-shaped signs',
            f"Moon {float(moon_lon):.6f}°; Mercury "
            f"{float(mercury_lon):.6f}° · "
            '[human-signs:Gemini,Virgo,Libra,Aquarius,Sagittarius-0-15]',
            (
                _ancient_subject(chrt, astrology.SE_MOON, 'teaching_moon'),
                _ancient_subject(
                    chrt, astrology.SE_MERCURY, 'teaching_mercury',
                ),
            ),
        )
    configured = _ancient_relation_clause(
        chrt, astrology.SE_MOON, astrology.SE_MERCURY,
        (0, 60, 90, 120, 180), 'Moon and Mercury configured',
        'teaching_pair',
    )
    return _ancient_compound_event(
        'hephaistion_teaching',
        (full, moon_place, mercury_place, eastern, human, configured),
        source='Heph. App. C §3',
    )


