def _ancient_good_phase_clause(
        chrt, pid, phase_policy, phase_policy_context_key,
        visibility_policy, visibility_policy_context_key, context):
    selected = _ancient_selected(
        phase_policy, _ANCIENT_GOOD_PHASE_POLICIES,
        context, phase_policy_context_key,
    )
    if selected is None or selected['value'] == 'source_phrase_only':
        return None
    phase = 'visible' if selected['value'] == 'visible' else 'eastern'
    clause = _ancient_solar_phase_clause(
        chrt, pid, phase, visibility_policy,
        visibility_policy_context_key, context,
        label='good phase', role='good_phase_subject',
    )
    if clause is not None:
        clause['policy'] = selected
        clause['evidence'] += (
            f" · [good-phase-policy:{selected['value'].replace('_', '-')}]"
        )
    return clause


