def _dorotheus_friendship_type_condition_event(
        chrt, friendship_type='jupiter',
        phase_policy='visible', phase_policy_context_key=None,
        place_policy='nechepso_eight', place_policy_context_key=None,
        harm_policy='malefic_testimony', harm_policy_context_key=None,
        visibility_policy='hellenistic_15_degree',
        visibility_policy_context_key=None, context=None, **_):
    kind = str(friendship_type or '').strip().lower().replace('-', '_')
    if kind not in {'jupiter', 'venus', 'mercury', 'malefic'}:
        return None
    if kind == 'jupiter':
        phase = _ancient_good_phase_clause(
            chrt, astrology.SE_JUPITER, phase_policy,
            phase_policy_context_key, visibility_policy,
            visibility_policy_context_key, context,
        )
        place = _ancient_place_clause(
            chrt, astrology.SE_JUPITER, policy=place_policy,
            policy_context_key=place_policy_context_key,
            context=context, role='friendship_jupiter',
        )
        free = _ancient_no_class_testimony_clause(
            chrt, astrology.SE_JUPITER,
            (astrology.SE_MARS, astrology.SE_SATURN), (90, 180),
            'free from malefic square or diameter',
            'friendship_malefic_exclusion',
        )
        clauses = (phase, place, free)
    elif kind == 'venus':
        place = _ancient_place_clause(
            chrt, astrology.SE_VENUS, policy=place_policy,
            policy_context_key=place_policy_context_key,
            context=context, role='friendship_venus',
        )
        if place is not None:
            venus = _planet(chrt, astrology.SE_VENUS)
            longitude = _lon(venus) if venus is not None else None
            if longitude is not None and _sign(longitude) == 11:
                place['evidence'] += ' · [Pisces:source-intensifier]'
        clauses = (place,)
    elif kind == 'mercury':
        place = _ancient_place_clause(
            chrt, astrology.SE_MERCURY, policy=place_policy,
            policy_context_key=place_policy_context_key,
            context=context, role='friendship_mercury',
        )
        harm = _ancient_unharmed_clause(
            chrt, astrology.SE_MERCURY, policy=harm_policy,
            policy_context_key=harm_policy_context_key, context=context,
        )
        testimony = _ancient_benefic_testimony_clause(
            chrt, astrology.SE_MERCURY, require_both=True,
            label='Jupiter and Venus testify to Mercury',
        )
        clauses = (place, harm, testimony)
    else:
        qualified = []
        for pid in (astrology.SE_MARS, astrology.SE_SATURN):
            place = _ancient_place_clause(
                chrt, pid, policy=place_policy,
                policy_context_key=place_policy_context_key,
                context=context, role='friendship_malefic',
            )
            body = _planet(chrt, pid)
            longitude = _lon(body) if body is not None else None
            domicile = None
            if (longitude is not None
                    and _domicile_ruler_at(chrt, _sign(longitude)) == pid):
                domicile = _ancient_clause(
                    'malefic in its own place',
                    f"{planet_name_from_id(pid).title()} in domicile sign "
                    f"{_sign(longitude)} · [dignity-frame:profile]",
                    (_ancient_subject(chrt, pid, 'friendship_malefic'),),
                )
            witness = _ancient_benefic_testimony_clause(
                chrt, pid, require_both=False,
                label='malefic sees a benefic',
            )
            event = _ancient_compound_event(
                f"dorotheus_{planet_name_from_id(pid)}_friendship",
                (place, domicile, witness), pid=int(pid),
            )
            if event is not None:
                qualified.append(event)
        if not qualified:
            return None
        clauses = (qualified[0],)
    return _ancient_compound_event(
        'dorotheus_friendship_type_condition', clauses,
        source='Dor. Excerpt XVI §2–5', friendship_type=kind,
    )


