def evaluate_predicate(name, chrt, args=None, context=None):
    """Dispatch a named predicate against a chart.

    `args` is the rule block's declared kwargs (TOML inline table).
    `context` is reserved for discipline-specific state (e.g. horary
    significator houses). When non-None it is forwarded as a `context`
    kwarg; predicates that don't declare it absorb it via **kwargs.
    """
    fn = PREDICATES.get(name)
    if fn is None:
        _log.warning("corpus: unknown predicate %r", name)
        return False
    call_args = dict(args or {})
    if context is not None:
        call_args['context'] = context
    try:
        with semantic_scope(args, context, root=True):
            return bool(fn(chrt, **call_args))
    except Exception:
        _log.exception("corpus: predicate %s failed with args=%r", name, args)
        return False


# ─────────────────────────────────────────────────────────────
# Rule timing — typed future-perfection witness
# ─────────────────────────────────────────────────────────────

_SIGN_SHORT = ('Ari', 'Tau', 'Gem', 'Can', 'Leo', 'Vir',
               'Lib', 'Sco', 'Sag', 'Cap', 'Aqu', 'Pis')
_SIGN_LONG = ('Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo',
              'Libra', 'Scorpio', 'Sagittarius', 'Capricorn',
              'Aquarius', 'Pisces')
# Sign quality → Lilly's sign-class timing unit (CA II, "When the thief
# shall be known", "Time when he will returne", etc.):
#   moveable signs  (Ari/Can/Lib/Cap) → days
#   common signs    (Gem/Vir/Sag/Pis) → weeks
#   fixed signs     (Tau/Leo/Sco/Aqu) → months
_MOVEABLE = {0, 3, 6, 9}
_COMMON   = {2, 5, 8, 11}
_FIXED    = {1, 4, 7, 10}

def _sign_class_unit(sign_idx):
    if sign_idx in _MOVEABLE: return 'days'
    if sign_idx in _COMMON:   return 'weeks'
    if sign_idx in _FIXED:    return 'months'
    return 'days'


def compute_timing_addendum(spec, chrt, context=None, semantic_args=None):
    """Build timing evidence under the same semantic frame as its rule.

    Timing is deliberately downstream of the canonical perfection event.  A
    present arc is not a promise: separating, station-blocked, ingress-blocked,
    unresolved, and sign-configuration relations therefore produce no text.
    """
    with semantic_scope(semantic_args, context, root=True):
        return _compute_timing_addendum_scoped(
            spec, chrt, context=context, semantic_args=semantic_args,
        )


def _timing_actor(chrt, spec, context, side):
    """Resolve one explicitly authored timing actor and its display label."""
    if side == 'from':
        kind = spec.get('from_kind', 'body')
        body_field = 'from'
        house_field = 'from_house'
        key_field = 'from_house_key'
    else:
        kind = spec.get('to', 'body')
        body_field = 'to_body'
        house_field = 'house'
        key_field = 'house_key'

    if kind == 'body':
        body_name = spec.get(body_field)
        if not body_name:
            return None
        pid = _pid(body_name)
        if pid is None:
            return None
        label = planet_name_from_id(pid).title()
    elif kind == 'lord_of_house':
        house = spec.get(house_field)
        context_key = spec.get(key_field)
        if context_key:
            if not isinstance(context, dict) or context_key not in context:
                return None
            house = context[context_key]
        try:
            house = int(house)
        except (TypeError, ValueError):
            return None
        if not 1 <= house <= 12:
            return None
        pid = _lord_of_house(chrt, house)
        if pid is None:
            return None
        label = f"{planet_name_from_id(pid).title()} (lord of H{house})"
    else:
        return None

    if _planet(chrt, pid) is None:
        return None
    return pid, label


def _compute_timing_addendum_scoped(spec, chrt, context=None,
                                     semantic_args=None):
    """Build a one-line timing addendum for a rule body.

    The timing block must identify both actors and an aspect set.  The orb is
    inherited from the resolved predicate arguments so timing cannot silently
    use a different doctrine from the verdict it annotates.

        [rule.timing]
        from = "sun"                # body whose motion drives the timing
        to = "lord_of_house"        # 'body' or 'lord_of_house'
        to_body = "saturn"          # used when to == 'body'
        house_key = "quesited_house"# used when to == 'lord_of_house';
                                    # context key; if absent, 'house' field
        house = 7                   # static house if no context key
        aspects = [0, 60, 90, 120, 180]
        unit = "sign"               # 'sign' (Lilly) or 'days' (fixed unit)

    Returns an addendum only for a future/current exact degree perfection that
    survives the canonical station and sign-ingress stops.
    """
    if not isinstance(spec, dict) or not spec:
        return ''
    policy = _SEMANTIC_POLICY.get()
    frame = str(policy.get('aspect_frame', 'degree')).lower().replace('-', '_')
    if frame not in ('degree', 'zodiacal_degree'):
        return ''

    rule_args = semantic_args if isinstance(semantic_args, dict) else {}
    raw_aspects = spec.get('aspects', rule_args.get('aspects'))
    if not raw_aspects:
        return ''
    try:
        aspects = tuple(float(angle) for angle in tuple(raw_aspects))
    except (TypeError, ValueError):
        return ''
    if not aspects:
        return ''

    resolved_from = _timing_actor(chrt, spec, context, 'from')
    resolved_to = _timing_actor(chrt, spec, context, 'to')
    if resolved_from is None or resolved_to is None:
        return ''
    pid_from, from_label = resolved_from
    pid_to, to_label = resolved_to
    if pid_from == pid_to:
        return ''

    # A source-fixed timing relation inherits the predicate's authored orb;
    # configured and moiety policies derive their limits from the chart/pids.
    orb = rule_args.get('orb')
    boundary = str(spec.get('boundary', 'pair_signs'))
    state = _body_relation_state(
        chrt, pid_from, pid_to, aspects, orb=orb,
        orb_policy=rule_args.get('orb_policy'),
        aspect_frame=rule_args.get('aspect_frame', 'profile'),
        directions=('applying', 'exact'), boundary=boundary,
        required_applicator_pid=pid_from,
    )
    event = state.get('perfection')
    if not state.get('matched') or not isinstance(event, dict):
        return ''
    try:
        days = float(event['days'])
        arc = float(event['arc'])
        angle = float(event['angle'])
    except (KeyError, TypeError, ValueError):
        return ''
    if not (math.isfinite(days) and math.isfinite(arc)
            and math.isfinite(angle) and days >= 0.0 and arc >= 0.0):
        return ''

    aspect_word = {
        0.0: 'conjunction', 60.0: 'sextile', 90.0: 'square',
        120.0: 'trine', 180.0: 'opposition',
    }.get(angle, f"{angle:g}\N{DEGREE SIGN}")
    method = {
        'ephemeris': 'exact ephemeris',
        'bounded-linear': 'bounded linear fallback',
    }.get(event.get('method'), str(event.get('method') or 'perfection event'))
    result = (
        f"Timing — {from_label} perfects the {aspect_word} with {to_label} "
        f"in {days:.2f} days (arc {arc:.2f}\N{DEGREE SIGN}; {method})"
    )

    unit_mode = str(spec.get('unit', 'days')).lower().replace('-', '_')
    if unit_mode == 'days':
        return result + '.'
    if unit_mode != 'sign':
        return ''
    from_lon = _lon(_planet(chrt, pid_from))
    if from_lon is None:
        return ''
    sign_idx = _sign(from_lon)
    symbolic_unit = _sign_class_unit(sign_idx)
    return (
        f"{result}; symbolic sign scale {arc:.2f} {symbolic_unit} "
        f"from {_SIGN_SHORT[sign_idx]}."
    )


