    if predicate == 'lilly_multiple_peregrine_angular':
        try:
            minimum = max(1, int(args.get('minimum', 2)))
            angular = {int(value) for value in tuple(args.get(
                'angular_houses', (1, 4, 7, 10),
            ))}
        except (TypeError, ValueError):
            return None
        subjects = []
        for pid in _PLANET_IDS.values():
            body = _planet(chrt, pid)
            longitude = _lon(body) if body is not None else None
            if longitude is None or not _body_is_peregrine_pid(chrt, pid):
                continue
            house = _house_of_frame(
                chrt, longitude, 'regiomontanus_5deg',
            )
            if house not in angular:
                continue
            subjects.append(_lilly_position_subject(
                chrt, pid, role='peregrine_angular', house=house,
            ))
        if len(subjects) < minimum:
            return None
        labels = ', '.join(
            f"{subject['name'].title()} H{subject['house']}"
            for subject in subjects
        )
        return {
            'glyph': _GLYPH_MAP.get(f"planet_{subjects[0]['name']}"),
            'evidence': (
                f"{len(subjects)} peregrine angular bodies (minimum "
                f"{minimum}): {labels} · [dignity:Lilly] · "
                "[house-frame:R+5°]"
            ),
            'subjects': subjects,
            'geometry': 'lilly_peregrine_angular_count',
        }

    if predicate == 'lilly_goods_restored_strong_reception':
        if str(args.get(
                'reception_relation', 'unresolved',
        )).lower().replace('-', '_') != 'both_mutual_with_l8':
            return None
        try:
            houses = tuple(int(value) for value in tuple(args.get(
                'houses', (1, 2, 8),
            )))
        except (TypeError, ValueError):
            return None
        if len(houses) != 3:
            return None
        l1, l2, l8 = tuple(_lord_of_house(chrt, house) for house in houses)
        if any(pid is None for pid in (l1, l2, l8)):
            return None
        allowed = {str(value).lower() for value in tuple(args.get(
            'levels', ('domicile', 'exaltation'),
        ))}
        pairs = []
        for house, pid in ((houses[0], l1), (houses[1], l2)):
            toward_eight = sorted(
                allowed.intersection(_reception_levels_of(chrt, pid, l8)),
            )
            toward_actor = sorted(
                allowed.intersection(_reception_levels_of(chrt, l8, pid)),
            )
            pairs.append((house, pid, toward_eight, toward_actor))
        if not all(row[2] and row[3] for row in pairs):
            return None
        clauses = [
            f"L{house}↔L{houses[2]} "
            f"({'+'.join(forward)}/{'+'.join(reverse)})"
            for house, _pid_value, forward, reverse in pairs
        ]
        return {
            'glyph': _GLYPH_MAP.get(f'planet_{planet_name_from_id(l8)}'),
            'evidence': (
                ' + '.join(clauses) +
                " · [reception:both-mutual-with-L8] · [dignity:Lilly]"
            ),
            'subjects': [
                _lilly_position_subject(chrt, l1, role=f'lord_{houses[0]}'),
                _lilly_position_subject(chrt, l2, role=f'lord_{houses[1]}'),
                _lilly_position_subject(chrt, l8, role=f'lord_{houses[2]}'),
            ],
            'geometry': 'lilly_bound_mutual_reception',
        }
    return None


